"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None

    start = 1 if s[0] == "-" else 0
    body = s[start:]
    if not body:
        return None

    if body.count(".") > 1:
        return None

    parts = body.split(".")
    whole, fraction = parts[0], parts[1] if len(parts) == 2 else ""

    if not whole and not fraction:
        return None
    if any(not ch.isdigit() for ch in whole + fraction):
        return None
    if len(fraction) > 3:
        return None

    try:
        value = Decimal(s)
        cents = (value * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        )
        return int(cents)
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    currency = currency.strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    if (
        len(timestamp_text) != 16
        or timestamp_text[4] != "-"
        or timestamp_text[7] != "-"
        or timestamp_text[10] != " "
        or timestamp_text[13] != ":"
        or not timestamp_text[:4].isdigit()
        or not timestamp_text[5:7].isdigit()
        or not timestamp_text[8:10].isdigit()
        or not timestamp_text[11:13].isdigit()
        or not timestamp_text[14:16].isdigit()
    ):
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"].strip()
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    results = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        best_payment = None
        best_timestamp = None
        deadline = order["timestamp"] + timedelta(hours=72)

        for payment in records:
            if payment["type"] != "PAYMENT":
                continue
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["amount"] < 0:
                continue
            if payment["timestamp"] < order["timestamp"]:
                continue
            if payment["timestamp"] > deadline:
                continue

            if best_payment is None or payment["timestamp"] < best_timestamp:
                best_payment = payment
                best_timestamp = payment["timestamp"]

        if best_payment is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": best_payment["amount"],
            })

    return results


def compute_refunds(records):
    total = 0

    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += -record["amount"]

    return total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for result in matches:
        if result["status"] == "matched":
            matched_count += 1
            net_total += result["amount"]
        else:
            unmatched_ids.append(result["order_id"])

    unmatched_ids.sort()
    net_total -= refund_total

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids,
    }

