def build_summary(matches, refund_total):
    total_orders = 0
    matched_count = 0
    net_total = 0
    unmatched_ids = set()

    for match in matches:
        if match['status'] == 'matched':
            matched_count += 1
            net_total += match['amount']
        else:
            unmatched_ids.add(match['order_id'])

