from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a decimal amount into an integer number of cents."""
    if not isinstance(s, str):
        return None

    value = s.strip()
    if not value:
        return None

    if value.startswith("-"):
        digits = value[1:]
    else:
        digits = value

    if not digits:
        return None

    if digits.count(".") > 1:
        return None

    if "." in digits:
        whole, fraction = digits.split(".")
        if not whole or not whole.isdigit():
            return None
        if fraction and not fraction.isdigit():
            return None
        if len(fraction) > 3:
            return None
    else:
        if not digits.isdigit():
            return None

    try:
        amount = Decimal(value)
        if not amount.is_finite():
            return None
        cents = amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        return int(cents * 100)
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    """Parse one input line into a record dictionary, or return None."""
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type = fields[0].strip().upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    amount_text = fields[3].strip()
    currency = fields[4]
    timestamp_text = fields[5]

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if currency != "USD":
        return None

    if len(timestamp_text) != 16:
        return None
    if (
        timestamp_text[4] != "-"
        or timestamp_text[7] != "-"
        or timestamp_text[10] != " "
        or timestamp_text[13] != ":"
    ):
        return None
    date_part = timestamp_text[:10]
    time_part = timestamp_text[11:]
    if (
        not date_part[:4].isdigit()
        or not date_part[5:7].isdigit()
        or not date_part[8:10].isdigit()
        or not time_part[:2].isdigit()
        or not time_part[3:5].isdigit()
    ):
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER":
        if record_id != order_id or amount < 0:
            return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    """Parse valid records, retaining only the first valid record ID."""
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    """Match each order with the earliest qualifying payment."""
    payments_by_order = {}

    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] >= 0:
            order_id = record["order_id"]
            payments_by_order.setdefault(order_id, []).append(record)

    matches = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        order_id = order["order_id"]
        latest_time = order["timestamp"] + timedelta(hours=72)
        chosen_payment = None

        for payment in payments_by_order.get(order_id, []):
            if (
                order["timestamp"]
                <= payment["timestamp"]
                <= latest_time
            ):
                if (
                    chosen_payment is None
                    or payment["timestamp"] < chosen_payment["timestamp"]
                ):
                    chosen_payment = payment

        if chosen_payment is None:
            matches.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            matches.append({
                "order_id": order_id,
                "status": "matched",
                "amount": chosen_payment["amount"],
            })

    return matches


def compute_refunds(records):
    """Return the total absolute value of all negative payment amounts."""
    refund_total = 0

    for record in records:
        if (
            record.get("type") == "PAYMENT"
            and record.get("amount", 0) < 0
        ):
            refund_total += abs(record["amount"])

    return refund_total


def build_summary(matches, refund_total):
    """Build a summary of matched and unmatched orders."""
    total_orders = len(matches)
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for result in matches:
        if result.get("status") == "matched":
            matched_count += 1
            if "payment_amount" in result:
                net_total += result["payment_amount"]
            elif "amount" in result:
                net_total += result["amount"]
        else:
            unmatched_ids.append(result.get("order_id"))

    unmatched_ids.sort()

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

