"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    try:
        if s.count('.') > 1 or any(c not in '0123456789.-' for c in s):
            return None
        if s.count('.') == 1:
            integer_part, fractional_part = s.split('.')
            if len(fractional_part) > 3:
                return None
            fractional_part = fractional_part.ljust(3, '0')[:3]  # Pad or truncate to 3 digits
            s = f"{integer_part}.{fractional_part}"
        amount = Decimal(s)
        return int(amount.to_integral_value(rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount_str, currency, timestamp_str = fields
    record_type = record_type.upper().strip()
    record_id = record_id.strip()
    order_id = order_id.strip()
    currency = currency.strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id or (record_type == 'ORDER' and record_id != order_id):
        return None
    if currency != 'USD':
        return None
    amount = parse_amount(amount_str)
    if amount is None or (record_type == 'ORDER' and amount < 0):
        return None
    if record_type == 'PAYMENT' and amount >= 0:
        return None
    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_record_ids = set()
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_record_ids:
            records.append(record)
            seen_record_ids.add(record['record_id'])
    return records


def match_payments(records):
    results = []
    for record in records:
        if record['type'] == 'ORDER':
            order_id = record['order_id']
            order_timestamp = record['timestamp']
            matched_payment = None

            for payment in records:
                if (payment['type'] == 'PAYMENT' and 
                    payment['order_id'] == order_id and 
                    payment['amount'] >= 0 and 
                    order_timestamp <= payment['timestamp'] <= order_timestamp + timedelta(hours=72)):
                    if matched_payment is None or payment['timestamp'] < matched_payment['timestamp']:
                        matched_payment = payment

            if matched_payment:
                results.append({
                    'order_id': order_id,
                    'status': 'matched',
                    'amount': matched_payment['amount']
                })
            else:
                results.append({
                    'order_id': order_id,
                    'status': 'unmatched',
                    'amount': 0
                })
    return results


def compute_refunds(records):
    total_refund = 0
    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0:
            total_refund += abs(record['amount'])
    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'] == 'unmatched')

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Return an amount as integer cents, or None when it is invalid."""
    if not isinstance(s, str):
        return None

    value = s.strip()
    if not value:
        return None

    if value.startswith("-"):
        digits = value[1:]
    else:
        digits = value

    parts = digits.split(".")
    if len(parts) > 2 or not parts[0].isdigit():
        return None
    if len(parts) == 2 and (
        not parts[1].isdigit() or not 1 <= len(parts[1]) <= 4
    ):
        return None

    try:
        amount = Decimal(value)
        if not amount.is_finite():
            return None
        cents = amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        return int(cents * 100)
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    """Parse one input line into a record dictionary, or return None."""
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type = fields[0].upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    amount_text = fields[3]
    currency = fields[4]
    timestamp_text = fields[5]

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None

    if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": "USD",
        "timestamp": timestamp,
    }


def load_records(text):
    """Load all valid records from a text export."""
    if not isinstance(text, str):
        return []

    records = []
    seen_record_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_record_ids:
            continue

        seen_record_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    """Return payment-to-order matches."""
    if not isinstance(records, list):
        return []

    payments_by_order = {}
    for source_index, record in enumerate(records):
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue

        amount = record.get("amount")
        if not isinstance(amount, int) or amount < 0:
            continue

        order_id = record.get("order_id")
        timestamp = record.get("timestamp")
        if not isinstance(order_id, str) or not isinstance(timestamp, datetime):
            continue

        payments_by_order.setdefault(order_id, []).append(
            (timestamp, source_index, amount)
        )

    results = []

    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "ORDER":
            continue

        order_id = record.get("order_id")
        order_timestamp = record.get("timestamp")
        candidates = []

        if isinstance(order_id, str) and isinstance(order_timestamp, datetime):
            latest_timestamp = order_timestamp + timedelta(hours=72)

            for payment_timestamp, source_index, amount in payments_by_order.get(
                order_id, []
            ):
                if order_timestamp <= payment_timestamp <= latest_timestamp:
                    candidates.append(
                        (payment_timestamp, source_index, amount)
                    )

        if candidates:
            payment_timestamp, source_index, amount = min(
                candidates,
                key=lambda item: (item[0], item[1]),
            )
            results.append(
                {
                    "order_id": order_id,
                    "status": "matched",
                    "amount": amount,
                }
            )
        else:
            results.append(
                {
                    "order_id": order_id,
                    "status": "unmatched",
                    "amount": 0,
                }
            )

    return results


def compute_refunds(records):
    """Return the total refunds in integer cents."""
    if not isinstance(records, list):
        return 0

    total = 0
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue

        amount = record.get("amount")
        if type(amount) is int and amount < 0:
            total += -amount

    return total


def build_summary(matches, refund_total):
    """Build a settlement summary."""
    if not isinstance(matches, list):
        matches = []

    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for result in matches:
        if not isinstance(result, dict):
            continue

        status = result.get("status")
        if status == "matched":
            matched_count += 1
            amount = result.get("amount", result.get("payment_amount", 0))
            if isinstance(amount, int):
                net_total += amount
        else:
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.append(order_id)

    if type(refund_total) is int and refund_total > 0:
        net_total -= refund_total

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

