"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s.strip())
        return int(amount * 100)  # Convert to cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    parts = line.split('|')
    if len(parts) != 6:
        return None
    record_type = parts[0].strip().upper()
    record_id = parts[1].strip()
    order_id = parts[2].strip()
    amount = parse_amount(parts[3].strip())
    currency = parts[4].strip()
    timestamp = parts[5].strip()

    if record_type not in ['ORDER', 'PAYMENT'] or record_id != order_id or currency != 'USD' or amount is None:
        return None

    try:
        timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record is not None and record['record_id'] not in seen_ids:
            seen_ids.add(record['record_id'])
            records.append(record)
    return records


def match_payments(records):
    results = []
    for record in records:
        if record['type'] == 'ORDER':
            order_id = record['order_id']
            order_timestamp = record['timestamp']
            matched_payment = None

            for payment in records:
                if (payment['type'] == 'PAYMENT' and 
                    payment['record_id'] != order_id and 
                    payment['timestamp'] >= order_timestamp and 
                    payment['timestamp'] <= order_timestamp + timedelta(hours=72) and 
                    payment['amount'] >= 0):

                    if matched_payment is None or payment['timestamp'] < matched_payment['timestamp']:
                        matched_payment = payment

            if matched_payment:
                results.append({
                    'order_id': order_id,
                    'status': 'matched',
                    'amount': matched_payment['amount']
                })
            else:
                results.append({
                    'order_id': order_id,
                    'status': 'unmatched',
                    'amount': 0
                })
    return results


def compute_refunds(records):
    # Placeholder for future implementation
    return 0


def build_summary(matches, refund_total):
    return {
        'total_orders': len(matches),
        'matched_count': sum(1 for match in matches if match['status'] == 'matched'),
        'net_total': sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total,
        'unmatched_ids': sorted(set(match['order_id'] for match in matches if match['status'] != 'matched'))
    }

