"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    import re
    if not isinstance(s, str):
        return None
    value = s.strip()
    if not re.fullmatch(r"-?\d+(?:\.\d{1,3})?", value):
        return None
    try:
        amount = Decimal(value)
        return int((amount * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        ))
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None


def parse_record(line):
    import re
    if not isinstance(line, str):
        return None
    parts = line.split("|")
    if len(parts) != 6:
        return None

    record_type = parts[0].strip().upper()
    record_id = parts[1].strip()
    order_id = parts[2].strip()
    amount_text = parts[3].strip()
    currency = parts[4].strip()
    timestamp_text = parts[5].strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    if currency != "USD":
        return None
    if not re.fullmatch(r"-?\d+(?:\.\d{1,3})?", amount_text):
        return None

    try:
        numeric_amount = Decimal(amount_text)
    except (InvalidOperation, ValueError):
        return None

    if record_type == "ORDER" and numeric_amount < 0:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if not re.fullmatch(r"\d{4}-\d{2}-\d{2} \d{2}:\d{2}", timestamp_text):
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue
        if record["record_id"] in seen:
            continue
        seen.add(record["record_id"])
        records.append(record)
    return records


def match_payments(records):
    orders = []
    payments = []
    for record in records:
        if record["type"] == "ORDER":
            orders.append(record)
        elif record["type"] == "PAYMENT" and record["amount"] >= 0:
            payments.append(record)

    results = []
    for order in orders:
        earliest = None
        deadline = order["timestamp"] + timedelta(hours=72)
        for payment in payments:
            if payment["order_id"] != order["order_id"]:
                continue
            if order["timestamp"] <= payment["timestamp"] <= deadline:
                if earliest is None or payment["timestamp"] < earliest["timestamp"]:
                    earliest = payment

        if earliest is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": earliest["amount"],
            })
    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += abs(record["amount"])
    return total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for result in matches:
        if result.get("status") == "matched":
            matched_count += 1
            net_total += result.get("amount", 0)
        else:
            unmatched_ids.append(result.get("order_id"))

    unmatched_ids.sort()
    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

