"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        if not isinstance(s, str):
            return None
        text = s.strip()
        if not text:
            return None
        if text.startswith("-"):
            body = text[1:]
            if not body:
                return None
        else:
            body = text
        if body.count(".") > 1:
            return None
        parts = body.split(".")
        if not parts[0].isdigit():
            return None
        if len(parts) == 2 and (not parts[1].isdigit() or len(parts[1]) > 3):
            return None
        value = Decimal(text)
        cents = (value * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        )
        return int(cents)
    except (InvalidOperation, ValueError, TypeError, ArithmeticError):
        return None


def parse_record(line):
    try:
        if not isinstance(line, str):
            return None
        fields = line.split("|")
        if len(fields) != 6:
            return None

        record_type = fields[0].strip().upper()
        record_id = fields[1].strip()
        order_id = fields[2].strip()
        currency = fields[4].strip()
        timestamp_text = fields[5].strip()

        if record_type not in ("ORDER", "PAYMENT"):
            return None
        if not record_id or not order_id:
            return None
        if record_type == "ORDER" and record_id != order_id:
            return None
        if currency != "USD":
            return None

        amount = parse_amount(fields[3])
        if amount is None:
            return None
        if record_type == "ORDER" and amount < 0:
            return None

        if len(timestamp_text) != 16:
            return None
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
        if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
            return None

        return {
            "type": record_type,
            "record_id": record_id,
            "order_id": order_id,
            "amount": amount,
            "currency": currency,
            "timestamp": timestamp,
        }
    except (ValueError, TypeError, OverflowError):
        return None


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if isinstance(record, dict):
            record_id = record["record_id"]
            if record_id not in seen:
                seen.add(record_id)
                records.append(record)
    return records


def match_payments(records):
    if not isinstance(records, list):
        return []

    payments = []
    orders = []
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") == "PAYMENT":
            if record.get("amount", 0) >= 0:
                payments.append(record)
        elif record.get("type") == "ORDER":
            orders.append(record)

    results = []
    for order in orders:
        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        chosen = None

        if order_time is not None:
            latest = order_time + timedelta(hours=72)
            for payment in payments:
                if payment.get("order_id") != order_id:
                    continue
                payment_time = payment.get("timestamp")
                if payment_time is None:
                    continue
                if order_time <= payment_time <= latest:
                    if chosen is None or payment_time < chosen.get("timestamp"):
                        chosen = payment

        if chosen is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": chosen.get("amount"),
            })
    return results


def compute_refunds(records):
    total = 0
    if not isinstance(records, list):
        return total
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        amount = record.get("amount")
        if isinstance(amount, int) and amount < 0:
            total += -amount
    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, list):
        matches = []

    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for result in matches:
        if not isinstance(result, dict):
            continue
        if result.get("status") == "matched":
            matched_count += 1
            net_total += result.get("amount", 0)
        elif result.get("status") == "unmatched":
            unmatched_ids.append(result.get("order_id"))

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a decimal monetary value to an integer number of cents."""
    if not isinstance(s, str):
        return None

    value = s.strip()
    if not value:
        return None

    sign = ""
    digits = value
    if digits[:1] in {"+", "-"}:
        sign, digits = digits[0], digits[1:]

    if not digits or digits.count(".") > 1:
        return None

    whole, dot, fraction = digits.partition(".")
    if not whole.isdigit() or (dot and not fraction.isdigit()):
        return None

    try:
        amount = Decimal(sign + digits)
        cents = amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        return int(cents * 100)
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None


def parse_record(line):
    """Parse one input line into a record dictionary, or return None."""
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type = fields[0].strip().upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    amount_text = fields[3]
    currency = fields[4]
    timestamp_text = fields[5]

    if record_type not in {"ORDER", "PAYMENT"}:
        return None
    if not record_id or not order_id:
        return None
    if currency != "USD":
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": "USD",
        "timestamp": timestamp,
    }


def load_records(text):
    """Parse valid records, retaining only the first valid record ID."""
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    """Match each order with its earliest qualifying payment."""
    orders = []
    payments = []

    for record in records:
        if record["type"] == "ORDER":
            orders.append(record)
        elif record["type"] == "PAYMENT" and record["amount"] >= 0:
            payments.append(record)

    matches = []

    for order in orders:
        earliest = order["timestamp"]
        latest = earliest + timedelta(hours=72)
        candidates = []

        for source_index, payment in enumerate(payments):
            if (
                payment["order_id"] == order["order_id"]
                and earliest <= payment["timestamp"] <= latest
            ):
                candidates.append((payment["timestamp"], source_index, payment))

        if candidates:
            candidates.sort(key=lambda item: (item[0], item[1]))
            payment = candidates[0][2]
            matches.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": payment["amount"],
            })
        else:
            matches.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })

    return matches


def compute_refunds(records):
    """Return the total absolute value of all negative payment amounts."""
    total = 0

    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += abs(record["amount"])

    return total


def build_summary(matches, refund_total):
    """Build a summary of order and payment matching results."""
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for result in matches:
        if result["status"] == "matched":
            matched_count += 1
            net_total += result["amount"]
        else:
            unmatched_ids.append(result["order_id"])

    unmatched_ids.sort()

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

