      "quote": "Implement `match_payments(records)` with one result for every order."
    },
    {
      "id": "P4-L4",
      "quote": "- For each order, consider only non-negative `PAYMENT` records with the same `order_id`."
    },
    {
      "id": "P4-L5",
      "quote": "- A payment qualifies when its naive UTC timestamp is at or after the order timestamp and at or before exactly 72 hours after it;"
