      "id": "P4-L6",
      "quote": "both endpoints are included."
    },
    {
      "id": "P4-L7",
      "quote": "- Negative payments are refunds and never qualify as matched payments."
    },
    {
      "id": "P4-L8",
      "quote": "- Choose the qualifying payment with the earliest timestamp;"
    },
    {
      "id": "P4-L9",
      "quote": "break exact timestamp ties by retained source order."
    },
