    if not text:
        return None
    if text.count(".") > 1:
        return None
    parts = text.split(".")
    integer_part = parts[0]
    fractional_part = parts[1] if len(parts) == 2 else ""
    if not integer_part and not fractional_part:
        return None
    for character in integer_part + fractional_part:
        if character < "0" or character > "9":
