    if len(fractional_part) > 3:
        return None
    try:
        value = Decimal(s)
        cents = value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        return int(cents * 100)
    except (InvalidOperation, ValueError, OverflowError):
        return None


