        record_id = record["record_id"]
        if record_id in seen_record_ids:
            continue

        seen_record_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    """Match each order with its earliest qualifying payment."""
    if not isinstance(records, list):
        return []

    results = []

    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue

        order_id = order.get("order_id")
        order_timestamp = order.get("timestamp")
        earliest_payment = None

        if order_id is not None and isinstance(order_timestamp, datetime):
            latest_timestamp = order_timestamp + timedelta(hours=72)

            for payment in records:
                if not isinstance(payment, dict):
                    continue
                if payment.get("type") != "PAYMENT":
                    continue
                if payment.get("order_id") != order_id:
                    continue

                amount = payment.get("amount")
                payment_timestamp = payment.get("timestamp")

                if not isinstance(amount, int) or isinstance(amount, bool):
                    continue
                if amount < 0:
                    continue
                if not isinstance(payment_timestamp, datetime):
                    continue
                if payment_timestamp < order_timestamp:
                    continue
                if payment_timestamp > latest_timestamp:
                    continue

                if (
                    earliest_payment is None
                    or payment_timestamp < earliest_payment["timestamp"]
                ):
                    earliest_payment = payment

        if earliest_payment is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": earliest_payment["amount"],
            })

    return results


def compute_refunds(records):
    """Return the total absolute value of all negative payment amounts."""
    if not isinstance(records, list):
        return 0

    refund_total = 0

    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue

        amount = record.get("amount")
        if not isinstance(amount, int) or isinstance(amount, bool):
            continue
        if amount < 0:
            refund_total += abs(amount)

    return refund_total


def build_summary(matches, refund_total):
    """Build the reconciliation summary for the supplied match results."""
    if not isinstance(matches, list):
        matches = []

    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for result in matches:
        if not isinstance(result, dict):
            continue

        if result.get("status") == "matched":
            matched_count += 1
            amount = result.get("amount", 0)

            if isinstance(amount, bool):
                amount = 0

            try:
                net_total += int(amount)
            except (TypeError, ValueError, OverflowError):
                pass
        elif result.get("status") == "unmatched":
            order_id = result.get("order_id")
            if order_id is not None:
                unmatched_ids.append(order_id)

    if (
        isinstance(refund_total, int)
        and not isinstance(refund_total, bool)
        and refund_total > 0
    ):
        net_total -= refund_total

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

