    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id:
        return None

    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    if currency != "USD":
        return None

    if not _TIMESTAMP_PATTERN.fullmatch(timestamp_text):
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    """Parse all valid records from a text export."""
    if not isinstance(text, str):
        return []

    records = []
    seen_record_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_record_ids:
            continue

        seen_record_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    orders = [record for record in records if record["type"] == "ORDER"]
    payments = [record for record in records if record["type"] == "PAYMENT"]

    results = []

    for order in orders:
        best_payment = None
        deadline = order["timestamp"] + timedelta(hours=72)

        for payment in payments:
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["amount"] < 0:
                continue
            if not (order["timestamp"] <= payment["timestamp"] <= deadline):
                continue

            if (
                best_payment is None
                or payment["timestamp"] < best_payment["timestamp"]
