"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None

    text = s
    if text.startswith("-"):
        text = text[1:]

    if not text or text.count(".") > 1:
        return None

    if "." in text:
        whole, fraction = text.split(".")
        if len(fraction) > 3:
            return None
    else:
        whole, fraction = text, ""

    if not whole and not fraction:
        return None
    if not all(char.isdigit() for char in whole + fraction):
        return None

    try:
        value = Decimal(s) * Decimal("100")
        rounded = value.quantize(Decimal("1"), rounding=ROUND_HALF_UP)
        return int(rounded)
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
    record_type = record_type.strip().upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    currency = currency.strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    if (
        len(timestamp_text) != 16
        or timestamp_text[4] != "-"
        or timestamp_text[7] != "-"
        or timestamp_text[10] != " "
        or timestamp_text[13] != ":"
        or not timestamp_text[:4].isdigit()
        or not timestamp_text[5:7].isdigit()
        or not timestamp_text[8:10].isdigit()
        or not timestamp_text[11:13].isdigit()
        or not timestamp_text[14:16].isdigit()
    ):
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue
        record_id = record["record_id"]
        if record_id in seen_ids:
            continue
        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    results = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        order_id = order["order_id"]
        order_time = order["timestamp"]
        latest_time = order_time + timedelta(hours=72)
        selected = None

        for payment in records:
            if payment["type"] != "PAYMENT":
                continue
            if payment["order_id"] != order_id:
                continue
            if payment["amount"] < 0:
                continue

            payment_time = payment["timestamp"]
            if order_time <= payment_time <= latest_time:
                if selected is None or payment_time < selected["timestamp"]:
                    selected = payment

        if selected is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": selected["amount"],
            })

    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += -record["amount"]
    return total


def build_summary(matches, refund_total):
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for match in matches:
        if match["status"] == "matched":
            matched_count += 1
            net_total += match["amount"]
        else:
            unmatched_ids.append(match["order_id"])

    unmatched_ids.sort()

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a decimal monetary string to an integer number of cents."""
    if not isinstance(s, str):
        return None

    value = s.strip()
    if not value or not re.fullmatch(r"-?\d+(?:\.\d{0,3})?", value):
        return None

    try:
        amount = Decimal(value)
        cents = (amount * Decimal("100")).quantize(
            Decimal("1"),
            rounding=ROUND_HALF_UP,
        )
    except (InvalidOperation, ValueError):
        return None

    if not amount.is_finite():
        return None

    return int(cents)


def parse_record(line):
    """Parse one input line into a record dictionary, or return None."""
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    (
        record_type,
        record_id,
        order_id,
        amount_text,
        currency,
        timestamp_text,
    ) = (field.strip() for field in fields)

    record_type = record_type.upper()

    if record_type not in ("ORDER", "PAYMENT"):
        return None

    if not record_id or not order_id:
        return None

    if record_type == "ORDER" and record_id != order_id:
        return None

    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    if not re.fullmatch(
        r"\d{4}-\d{2}-\d{2} \d{2}:\d{2}",
        timestamp_text,
    ):
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": "USD",
        "timestamp": timestamp,
    }


def load_records(text):
    """Parse valid records, keeping only the first valid record ID."""
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    """Match each order with the earliest qualifying payment."""
    if not isinstance(records, list):
        return []

    payments_by_order = {}

    for source_index, record in enumerate(records):
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue

        amount = record.get("amount")
        if not isinstance(amount, int) or amount < 0:
            continue

        order_id = record.get("order_id")
        payments_by_order.setdefault(order_id, []).append(
            (record.get("timestamp"), source_index, record)
        )

    results = []

    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "ORDER":
            continue

        order_id = record["order_id"]
        order_timestamp = record["timestamp"]
        latest_timestamp = order_timestamp + timedelta(hours=72)

        qualifying = []

        for payment_timestamp, source_index, payment in (
            payments_by_order.get(order_id, [])
        ):
            if order_timestamp <= payment_timestamp <= latest_timestamp:
                qualifying.append(
                    (payment_timestamp, source_index, payment)
                )

        if qualifying:
            _, _, payment = min(
                qualifying,
                key=lambda item: (item[0], item[1]),
            )
            results.append(
                {
                    "order_id": order_id,
                    "status": "matched",
                    "amount": payment["amount"],
                }
            )
        else:
            results.append(
                {
                    "order_id": order_id,
                    "status": "unmatched",
                    "amount": 0,
                }
            )

    return results


def compute_refunds(records):
    """Return the total absolute value of negative payment amounts."""
    if not isinstance(records, list):
        return 0

    total = 0

    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue

        amount = record.get("amount")
        if isinstance(amount, int) and amount < 0:
            total += abs(amount)

    return total


def build_summary(matches, refund_total):
    """Build the four-field reconciliation summary."""
    if not isinstance(matches, list):
        matches = []

    matched_count = 0
    matched_total = 0
    unmatched_ids = []

    for result in matches:
        if not isinstance(result, dict):
            continue

        if result.get("status") == "matched":
            matched_count += 1

            if "payment_amount" in result:
                matched_total += result["payment_amount"]
            else:
                matched_total += result.get("amount", 0)
        elif result.get("status") == "unmatched":
            unmatched_ids.append(result.get("order_id"))

    if not isinstance(refund_total, int):
        refund_total = 0

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": matched_total - refund_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

