"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    try:
        if s.count('.') > 1 or any(c not in '0123456789.-' for c in s):
            return None
        decimal_value = Decimal(s)
        if decimal_value.as_tuple().exponent < -2:
            return None
        return int(decimal_value.to_integral_value(rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount, currency, timestamp = map(str.strip, fields)
    if record_type.upper() not in ['ORDER', 'PAYMENT']:
        return None
    if record_type.upper() == 'ORDER' and record_id != order_id:
        return None
    if currency != 'USD':
        return None
    amount_parsed = parse_amount(amount)
    if amount_parsed is None or (record_type.upper() == 'ORDER' and amount_parsed < 0):
        return None
    try:
        timestamp_parsed = datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None
    return {
        'type': record_type.upper(),
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount_parsed,
        'currency': currency,
        'timestamp': timestamp_parsed
    }


def load_records(text):
    records = {}
    result = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in records:
            records[record['record_id']] = record
            result.append(record)
    return result


def match_payments(records):
    results = []
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = [record for record in records if record['type'] == 'PAYMENT' and record['amount'] >= 0]

    for order in orders:
        matched_payment = None
        order_id = order['order_id']
        order_timestamp = order['timestamp']
        order_time_limit = order_timestamp + timedelta(hours=72)

        for payment in payments:
            if payment['order_id'] == order_id and order_timestamp <= payment['timestamp'] <= order_time_limit:
                if matched_payment is None or payment['timestamp'] < matched_payment['timestamp']:
                    matched_payment = payment

        if matched_payment:
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': matched_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    total_refund = 0
    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0:
            total_refund += abs(record['amount'])
    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'] == 'unmatched')

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

