"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    value = s.strip()
    if not value:
        return None
    if value.startswith("-"):
        digits = value[1:]
    else:
        digits = value
    if not digits or digits.count(".") > 1:
        return None
    if "." in digits:
        whole, fraction = digits.split(".")
        if len(fraction) > 3:
            return None
    else:
        whole, fraction = digits, ""
    if not whole and not fraction:
        return None
    if not all("0" <= char <= "9" for char in whole + fraction):
        return None
    try:
        amount = Decimal(value)
        cents = (amount * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        )
        return int(cents)
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
    record_type = fields[0].strip().upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    currency = fields[4].strip()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    if currency != "USD":
        return None
    amount = parse_amount(fields[3])
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None
    timestamp_text = fields[5]
    if len(timestamp_text) != 16:
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": "USD",
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is None or record["record_id"] in seen:
            continue
        seen.add(record["record_id"])
        records.append(record)
    return records


def match_payments(records):
    orders = [r for r in records if r["type"] == "ORDER"]
    payments = [r for r in records if r["type"] == "PAYMENT"]
    results = []
    for order in orders:
        earliest = None
        deadline = order["timestamp"] + timedelta(hours=72)
        for payment in payments:
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["amount"] < 0:
                continue
            if not (order["timestamp"] <= payment["timestamp"] <= deadline):
                continue
            if earliest is None or payment["timestamp"] < earliest["timestamp"]:
                earliest = payment
        if earliest is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": earliest["amount"],
            })
    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += -record["amount"]
    return total


def build_summary(matches, refund_total):
    unmatched_ids = []
    matched_count = 0
    net_total = 0
    for result in matches:
        if result["status"] == "matched":
            matched_count += 1
            net_total += result["amount"]
        else:
            unmatched_ids.append(result["order_id"])
    unmatched_ids.sort()
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None

    s = s.strip()
    if not s or s.count('.') > 1 or any(c not in '0123456789.-' for c in s):
        return None

    if s.count('-') > 1 or (s.count('-') == 1 and s[0] != '-'):
        return None

    if s.count('.') == 1:
        integer_part, fractional_part = s.split('.')
        if len(fractional_part) > 3:
            return None
        try:
            amount = Decimal(s).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        except InvalidOperation:
            return None
    else:
        try:
            amount = Decimal(s)
        except InvalidOperation:
            return None

    return int(amount * 100)


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type = fields[0].strip().upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    amount_str = fields[3].strip()
    currency = fields[4].strip()
    timestamp_str = fields[5].strip()

    if record_type not in {'ORDER', 'PAYMENT'}:
        return None

    if not record_id or not order_id or (record_type == 'ORDER' and record_id != order_id):
        return None

    if currency != 'USD':
        return None

    amount = parse_amount(amount_str)
    if amount is None:
        return None

    if record_type == 'ORDER' and amount < 0:
        return None

    if record_type == 'PAYMENT' and amount > 0:
        return None

    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_record_ids = set()

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_record_ids:
            records.append(record)
            seen_record_ids.add(record['record_id'])

    return records


def match_payments(records):
    results = []

    for record in records:
        if record['type'] == 'ORDER':
            order_id = record['order_id']
            order_timestamp = record['timestamp']
            end_timestamp = order_timestamp + timedelta(hours=72)

            qualifying_payments = [
                r for r in records
                if r['type'] == 'PAYMENT' and
                r['order_id'] == order_id and
                r['amount'] >= 0 and
                order_timestamp <= r['timestamp'] <= end_timestamp
            ]

            if qualifying_payments:
                # Sort by timestamp, then by original order (index in records)
                qualifying_payments.sort(key=lambda r: (r['timestamp'], records.index(r)))
                earliest_payment = qualifying_payments[0]
                results.append({
                    'order_id': order_id,
                    'status': 'matched',
                    'amount': earliest_payment['amount']
                })
            else:
                results.append({
                    'order_id': order_id,
                    'status': 'unmatched',
                    'amount': 0
                })

    return results


def compute_refunds(records):
    refund_total = 0

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0:
            refund_total += abs(record['amount'])

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'] == 'unmatched')

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

