from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None

    text = s
    negative = text.startswith("-")
    if negative:
        text = text[1:]

    if not text or text.count(".") > 1:
        return None

    parts = text.split(".")
    integer_part = parts[0]
    fractional_part = parts[1] if len(parts) == 2 else ""

    if not integer_part and not fractional_part:
        return None
    if any(char < "0" or char > "9" for char in integer_part):
        return None
    if any(char < "0" or char > "9" for char in fractional_part):
        return None
    if len(fractional_part) > 3:
        return None

    try:
        value = Decimal("-" + text if negative else text)
        cents = value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        return int(cents * 100)
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()
    currency = currency.strip()

    if not record_id or not order_id:
        return None
    if currency != "USD":
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    if len(timestamp_text) != 16:
        return None

    for index, character in enumerate(timestamp_text):
        if index in (4, 7):
            if character != "-":
                return None
        elif index == 10:
            if character != " ":
                return None
        elif index == 13:
            if character != ":":
                return None
        elif not ("0" <= character <= "9"):
            return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue
        record_id = record["record_id"]
        if record_id in seen_ids:
            continue
        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    results = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        best_payment = None
        latest_allowed = order["timestamp"] + timedelta(hours=72)

        for payment in records:
            if payment["type"] != "PAYMENT":
                continue
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["amount"] < 0:
                continue
            if payment["timestamp"] < order["timestamp"]:
                continue
            if payment["timestamp"] > latest_allowed:
                continue
            if best_payment is None or payment["timestamp"] < best_payment["timestamp"]:
                best_payment = payment

        if best_payment is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": best_payment["amount"],
            })

    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += -record["amount"]
    return total


def build_summary(matches, refund_total):
    matched_total = 0
    matched_count = 0
    unmatched_ids = []

    for match in matches:
        if match["status"] == "matched":
            matched_count += 1
            matched_total += match["amount"]
        else:
            unmatched_ids.append(match["order_id"])

    unmatched_ids.sort()
    refund = refund_total if refund_total > 0 else 0

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": matched_total - refund,
        "unmatched_ids": unmatched_ids,
    }

"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a decimal monetary value to an integer number of cents."""
    if not isinstance(s, str):
        return None

    value = s.strip()
    if not value or re.fullmatch(r"-?\d+(?:\.\d{0,3})?", value) is None:
        return None

    try:
        amount = Decimal(value)
        if not amount.is_finite():
            return None

        cents = (amount * Decimal("100")).quantize(
            Decimal("1"),
            rounding=ROUND_HALF_UP,
        )
        return int(cents)
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None


def parse_record(line):
    """Parse one input line into a record dictionary."""
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields

    if record_type not in ("ORDER", "order", "PAYMENT", "payment"):
        return None

    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()

    if not record_id or not order_id:
        return None

    if record_type == "ORDER" and record_id != order_id:
        return None

    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    if re.fullmatch(
        r"\d{4}-\d{2}-\d{2} \d{2}:\d{2}",
        timestamp_text,
    ) is None:
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": "USD",
        "timestamp": timestamp,
    }


def load_records(text):
    """Parse all valid records from a text export."""
    if not isinstance(text, str):
        return []

    records = []
    seen_record_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_record_ids:
            continue

        seen_record_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    """Return the earliest qualifying payment for each order."""
    results = []

    for order in records:
        if order.get("type") != "ORDER":
            continue

        order_id = order["order_id"]
        order_time = order["timestamp"]
        latest_time = order_time + timedelta(hours=72)

        best_payment = None
        best_time = None

        for payment in records:
            if payment.get("type") != "PAYMENT":
                continue
            if payment.get("order_id") != order_id:
                continue
            if payment.get("amount", 0) < 0:
                continue

            payment_time = payment["timestamp"]
            if payment_time < order_time or payment_time > latest_time:
                continue

            if best_payment is None or payment_time < best_time:
                best_payment = payment
                best_time = payment_time

        if best_payment is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": best_payment["amount"],
            })

    return results


def compute_refunds(records):
    """Return the total refund amount in cents."""
    refund_total = 0

    for record in records:
        if record.get("type") != "PAYMENT":
            continue

        amount = record.get("amount")
        if amount is not None and amount < 0:
            refund_total += abs(amount)

    return refund_total


def build_summary(matches, refund_total):
    """Build a settlement summary."""
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for result in matches:
        if result.get("status") == "matched":
            matched_count += 1
            net_total += result.get("amount", 0)
        else:
            unmatched_ids.append(result.get("order_id"))

    net_total -= refund_total
    unmatched_ids.sort()

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids,
    }

