"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        if not isinstance(s, str):
            return None
        text = s.strip()
        if not text:
            return None
        sign = ""
        body = text
        if body.startswith("-"):
            sign = "-"
            body = body[1:]
        if not body or body.startswith("+"):
            return None
        if body.count(".") > 1:
            return None
        if "." in body:
            whole, fraction = body.split(".")
            if not whole or not fraction or len(fraction) > 3:
                return None
        else:
            whole, fraction = body, ""
        if not whole.isdigit() or (fraction and not fraction.isdigit()):
            return None
        value = Decimal(sign + body)
        cents = (value * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        )
        return int(cents)
    except (InvalidOperation, ValueError, TypeError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None
    parts = line.strip().split("|")
    if len(parts) != 6:
        return None
    record_type = parts[0].strip().upper()
    record_id = parts[1].strip()
    order_id = parts[2].strip()
    amount_text = parts[3].strip()
    currency = parts[4].strip()
    timestamp_text = parts[5].strip()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    if currency != "USD":
        return None
    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (ValueError, TypeError):
        return None
    if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue
        if record["record_id"] in seen:
            continue
        seen.add(record["record_id"])
        records.append(record)
    return records


def match_payments(records):
    orders = []
    payments = []
    for record in records:
        if record.get("type") == "ORDER":
            orders.append(record)
        elif record.get("type") == "PAYMENT" and record.get("amount", 0) >= 0:
            payments.append(record)

    results = []
    for order in orders:
        start = order["timestamp"]
        end = start + timedelta(hours=72)
        chosen = None
        for payment in payments:
            if payment["order_id"] != order["order_id"]:
                continue
            timestamp = payment["timestamp"]
            if start <= timestamp <= end:
                if chosen is None or timestamp < chosen["timestamp"]:
                    chosen = payment
        if chosen is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": chosen["amount"],
            })
    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if record.get("type") == "PAYMENT" and record.get("amount", 0) < 0:
            total += -record["amount"]
    return total


def build_summary(matches, refund_total):
    matched_count = 0
    net_total = 0
    unmatched_ids = []
    for result in matches:
        if result.get("status") == "matched":
            matched_count += 1
            net_total += result.get("amount", 0)
        else:
            unmatched_ids.append(result.get("order_id"))
    unmatched_ids.sort()
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

