{
  "rules": [
    {
      "id": "P4-L1",
      "quote": "`match_payments(records)` associates payments with orders by `order_id`."
    },
    {
      "id": "P4-L2",
      "quote": "- A non-refund payment qualifies only when its timestamp is at or after the order timestamp and no later than exactly 72 hours after it."
    },
    {
      "id": "P4-L3",
      "quote": "Both endpoints are included."
    },
    {
      "id": "P4-L4",
      "quote": "- If several payments qualify, use the one with the earliest timestamp."
    },
    {
      "id": "P4-L5",
      "quote": "Break an exact timestamp tie by retained source order."
    },
    {
      "id": "P4-L6",
      "quote": "- Negative payments are refunds and never qualify as matched payments."
    },
    {
      "id": "P4-L7",
      "quote": "- Return one result for every order, following retained order-record order."
    },
    {
      "id": "P4-L8",
      "quote": "Each result is an ordinary dictionary, never a tuple, with exactly `\"order_id\"`, `\"status\"`, and `\"amount\"`."
    },
    {
      "id": "P4-L10",
      "quote": "Status is exactly lowercase `\"matched\"` or `\"unmatched\"`."
    },
    {
      "id": "P4-L11",
      "quote": "An unmatched result has amount `0`."
    },
    {
      "id": "P3-L3",
      "quote": "- `\"net_total\"`: sum of the amounts of matched payments, in cents, not including refunds under the initial rule in this part;"
    },
    {
      "id": "P3-L4",
      "quote": "and - `\"unmatched_ids\"`: unmatched order IDs in ascending lexicographic order."
    }
