"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    value = s.strip()
    if not value:
        return None
    if value.startswith("-"):
        body = value[1:]
        if not body:
            return None
    else:
        body = value
    parts = body.split(".")
    if len(parts) > 2 or not parts[0] or not all("0" <= c <= "9" for c in parts[0]):
        return None
    if len(parts) == 2:
        if not parts[1] or len(parts[1]) > 3 or not all("0" <= c <= "9" for c in parts[1]):
            return None
    try:
        return int((Decimal(value) * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        ))
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
    type_value = fields[0].strip().upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    currency = fields[4].strip()
    if type_value not in ("ORDER", "PAYMENT") or not record_id or not order_id:
        return None
    if type_value == "ORDER" and record_id != order_id:
        return None
    if currency != "USD":
        return None
    amount = parse_amount(fields[3])
    if amount is None or (type_value == "ORDER" and amount < 0):
        return None
    timestamp_text = fields[5]
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None
    if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
        return None
    return {
        "type": type_value,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": "USD",
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is None or record["record_id"] in seen:
            continue
        seen.add(record["record_id"])
        records.append(record)
    return records


def match_payments(records):
    payments = [r for r in records if r.get("type") == "PAYMENT"]
    results = []
    for order in records:
        if order.get("type") != "ORDER":
            continue
        start = order["timestamp"]
        end = start + timedelta(hours=72)
        qualifying = [
            payment for payment in payments
            if payment.get("order_id") == order.get("order_id")
            and payment.get("amount", 0) >= 0
            and start <= payment.get("timestamp") <= end
        ]
        if qualifying:
            chosen = min(qualifying, key=lambda payment: payment["timestamp"])
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": chosen["amount"],
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
    return results


def compute_refunds(records):
    return sum(
        -record["amount"]
        for record in records
        if record.get("type") == "PAYMENT" and record.get("amount", 0) < 0
    )


def build_summary(matches, refund_total):
    matched = [item for item in matches if item.get("status") == "matched"]
    unmatched = sorted(
        item["order_id"] for item in matches
        if item.get("status") == "unmatched"
    )
    net_total = sum(item.get("amount", 0) for item in matched) - refund_total
    return {
        "total_orders": len(matches),
        "matched_count": len(matched),
        "net_total": net_total,
        "unmatched_ids": unmatched,
    }

