    try:
        timestamp = datetime.strptime(timestamp, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    # Validate non-empty RECORD_ID and ORDER_ID
    if not record_id or not order_id:
        return None

    # Return the parsed record as a dictionary
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": parsed_amount,
        "currency": currency,
        "timestamp": timestamp
    }


