"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    s = s.strip()
    try:
        amount = Decimal(s) * 100
        return int(amount.to_integral_value(rounding=ROUND_HALF_UP))
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.upper().strip()
    record_id = record_id.strip()
    order_id = order_id.strip()
    amount = amount.strip()
    currency = currency.strip()
    timestamp = timestamp.strip()

    if not all([record_id, order_id]) or record_type not in ['ORDER', 'PAYMENT']:
        return None

    if record_type == 'ORDER' and record_id != order_id:
        return None

    if currency != 'USD':
        return None

    amount_value = parse_amount(amount)
    if amount_value is None:
        return None

    try:
        timestamp_value = datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount_value,
        "currency": currency,
        "timestamp": timestamp_value
    }


def load_records(text):
    lines = text.strip().splitlines()
    return [parse_record(line) for line in lines if parse_record(line) is not None]


def match_payments(records):
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = [record for record in records if record['type'] == 'PAYMENT']
    results = []

    for order in orders:
        order_id = order['order_id']
        order_timestamp = order['timestamp']
        matching_payments = [
            payment for payment in payments
            if payment['order_id'] == order_id and 
            order_timestamp <= payment['timestamp'] <= order_timestamp + timedelta(hours=72) and 
            payment['amount'] >= 0
        ]

        if matching_payments:
            earliest_payment = min(matching_payments, key=lambda p: p['timestamp'])
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": earliest_payment['amount']
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0
            })

    return results


def compute_refunds(records):
    refunds = sum(record['amount'] for record in records if record['type'] == 'PAYMENT' and record['amount'] < 0)
    return abs(refunds)


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'] == 'unmatched')

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids
    }

