from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        if not isinstance(s, str):
            return None
        s = s.strip()
        if not s:
            return None
        negative = s.startswith("-")
        body = s[1:] if negative else s
        if not body or body.count(".") > 1:
            return None
        parts = body.split(".")
        if not parts[0].isdigit():
            return None
        if len(parts) == 2 and parts[1] and not parts[1].isdigit():
            return None
        if len(parts) == 2 and len(parts[1]) > 3:
            return None
        fraction = parts[1] if len(parts) == 2 else ""
        cents = int(parts[0]) * 100
        cents += int((fraction + "00")[:2] or "0")
        if len(fraction) == 3 and int(fraction[2]) >= 5:
            cents += 1
        return -cents if negative else cents
    except (ValueError, TypeError, IndexError):
        return None


def parse_record(line):
    try:
        if not isinstance(line, str):
            return None
        fields = line.split("|")
        if len(fields) != 6:
            return None
        record_type = fields[0].strip().upper()
        record_id = fields[1].strip()
        order_id = fields[2].strip()
        currency = fields[4].strip()
        timestamp_text = fields[5]
        if record_type not in ("ORDER", "PAYMENT"):
            return None
        if not record_id or not order_id or currency != "USD":
            return None
        if record_type == "ORDER" and record_id != order_id:
            return None
        amount = parse_amount(fields[3])
        if amount is None or (record_type == "ORDER" and amount < 0):
            return None
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
        if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
            return None
        return {
            "type": record_type,
            "record_id": record_id,
            "order_id": order_id,
            "amount": amount,
            "currency": "USD",
            "timestamp": timestamp,
        }
    except (ValueError, TypeError, OverflowError):
        return None


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            records.append(record)
    return records


