from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None

    if s.startswith("-"):
        number = s[1:]
    else:
        number = s

    if not number:
        return None

    if number.count(".") > 1:
        return None

    if "." in number:
        whole, fraction = number.split(".")
    else:
        whole, fraction = number, ""

    if not whole and not fraction:
        return None

    if any(character not in "0123456789" for character in whole + fraction):
        return None

    if len(fraction) > 3:
        return None

    try:
        value = Decimal(s)
        rounded = value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        return int(rounded * 100)
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields

    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id:
        return None

    if record_type == "ORDER" and record_id != order_id:
        return None

    currency = currency.strip()
    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    if (
        len(timestamp_text) != 16
        or timestamp_text[4] != "-"
        or timestamp_text[7] != "-"
        or timestamp_text[10] != " "
        or timestamp_text[13] != ":"
        or any(
            not timestamp_text[index].isdigit()
            for index in (0, 1, 2, 3, 5, 6, 8, 9, 11, 12, 14, 15)
        )
    ):
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        try:
            record = parse_record(line)
        except Exception:
            record = None

        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
