                continue
            if payment["order_id"] != order_id:
                continue
            if payment["amount"] < 0:
                continue
            if payment["timestamp"] < order_time:
                continue
            if payment["timestamp"] > latest_time:
                continue

            if (
                chosen_payment is None
                or payment["timestamp"] < chosen_payment["timestamp"]
            ):
                chosen_payment = payment

        if chosen_payment is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": chosen_payment["amount"],
            })

    return results


def compute_refunds(records):
    total = 0

    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += abs(record["amount"])

    return total


