from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None

    if s.startswith("-"):
        negative = True
        text = s[1:]
    else:
        negative = False
        text = s

    if not text:
        return None

    if text.count(".") > 1:
        return None

    if any(char != "." and char not in "0123456789" for char in text):
        return None

    if not any(char in "0123456789" for char in text):
        return None

    if "." in text:
        whole_text, fraction_text = text.split(".")
    else:
        whole_text = text
        fraction_text = ""

    if len(fraction_text) > 3:
        return None

    whole = int(whole_text) if whole_text else 0
    fraction = fraction_text.ljust(3, "0")
    cents = int(fraction[:2]) if fraction[:2] else 0

    if fraction[2] >= "5":
        cents += 1

    amount = whole * 100 + cents

    if negative:
        amount = -amount

    return amount


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields

    if record_type not in ("ORDER", "PAYMENT", "order", "payment"):
        return None

    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    currency = currency.strip()

    if not record_id or not order_id:
        return None

    if record_type == "ORDER" and record_id != order_id:
        return None

    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    if (
        len(timestamp_text) != 16
        or timestamp_text[4] != "-"
        or timestamp_text[7] != "-"
        or timestamp_text[10] != " "
        or timestamp_text[13] != ":"
        or not all(
            character.isdigit()
            for index, character in enumerate(timestamp_text)
            if index not in (4, 7, 10, 13)
        )
    ):
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

