                continue
            if record["order_id"] != order_id:
                continue
            if record["amount"] < 0:
                continue
            if record["timestamp"] < order_time:
                continue
            if record["timestamp"] > latest_time:
                continue

            if (
                earliest_payment is None
                or record["timestamp"] < earliest_payment["timestamp"]
            ):
                earliest_payment = record

        if earliest_payment is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": earliest_payment["amount"],
            })

    return results


def compute_refunds(records):
    total = 0

    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += abs(record["amount"])

    return total


def build_summary(matches, refund_total):
    matched_total = 0
