"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a decimal monetary value to integer cents."""
    if not isinstance(s, str):
        return None
    text = s.strip()
    if not text:
        return None
    if text.startswith("-"):
        body = text[1:]
        if not body:
            return None
    else:
        body = text
    if body.count(".") > 1:
        return None
    parts = body.split(".")
    if not parts[0] or not parts[0].isdigit():
        return None
    if len(parts) == 2 and (not parts[1].isdigit() or len(parts[1]) > 3):
        return None
    try:
        value = Decimal(text)
        return int((value * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        ))
    except (InvalidOperation, ValueError, TypeError):
        return None


def parse_record(line):
    """Parse one record line."""
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type = fields[0].strip().upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None

    record_id = fields[1].strip()
    order_id = fields[2].strip()
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(fields[3])
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None
    if fields[4].strip() != "USD":
        return None

    timestamp_text = fields[5]
    if (len(timestamp_text) != 16 or timestamp_text[4] != "-" or
            timestamp_text[7] != "-" or timestamp_text[10] != " " or
            timestamp_text[13] != ":" or
            not timestamp_text[:4].isdigit() or
            not timestamp_text[5:7].isdigit() or
            not timestamp_text[8:10].isdigit() or
            not timestamp_text[11:13].isdigit() or
            not timestamp_text[14:16].isdigit()):
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": "USD",
        "timestamp": timestamp,
    }


def load_records(text):
    """Parse valid records, retaining only the first valid record ID."""
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            records.append(record)
    return records


def match_payments(records):
    """Return one matching result for every order."""
    payments = [r for r in records if r["type"] == "PAYMENT"]
    results = []
    for order in records:
        if order["type"] != "ORDER":
            continue
        latest = order["timestamp"] + timedelta(hours=72)
        candidates = []
        for position, payment in enumerate(payments):
            if (payment["order_id"] == order["order_id"] and
                    payment["amount"] >= 0 and
                    order["timestamp"] <= payment["timestamp"] <= latest):
                candidates.append((payment["timestamp"], position, payment))
        if candidates:
            candidates.sort(key=lambda item: (item[0], item[1]))
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": candidates[0][2]["amount"],
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
    return results


def compute_refunds(records):
    """Compute the total refundable amount in cents."""
    total = 0
    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += abs(record["amount"])
    return total


def build_summary(matches, refund_total):
    """Build a settlement summary."""
    matched_count = 0
    net_total = 0
    unmatched_ids = []
    for result in matches:
        if result["status"] == "matched":
            matched_count += 1
            net_total += result["amount"]
        else:
            unmatched_ids.append(result["order_id"])
    unmatched_ids.sort()
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

