"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    value = s.strip()
    if not value:
        return None
    negative = value.startswith("-")
    digits = value[1:] if negative else value
    if not digits or digits.count(".") > 1:
        return None
    if "." in digits:
        whole, fraction = digits.split(".")
        if not whole or not whole.isdigit() or not fraction.isdigit():
            return None
        if len(fraction) > 3:
            return None
    elif not digits.isdigit():
        return None
    try:
        amount = Decimal(value)
        cents = (amount * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        )
        return int(cents)
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
    if record_type.upper() not in ("ORDER", "PAYMENT"):
        return None
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    currency = currency.strip()
    if not record_id or not order_id or currency != "USD":
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    amount = parse_amount(amount_text)
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None
    if len(timestamp_text) != 16:
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (ValueError, TypeError):
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": "USD",
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            records.append(record)
    return records


def match_payments(records):
    orders = []
    payments = []
    for record in records:
        if record["type"] == "ORDER":
            orders.append(record)
        elif record["type"] == "PAYMENT":
            payments.append(record)

    results = []
    for order in orders:
        earliest = None
        deadline = order["timestamp"] + timedelta(hours=72)
        for payment in payments:
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["amount"] < 0:
                continue
            if order["timestamp"] <= payment["timestamp"] <= deadline:
                if earliest is None or payment["timestamp"] < earliest["timestamp"]:
                    earliest = payment
        if earliest is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": earliest["amount"],
            })
    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += -record["amount"]
    return total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = 0
    net_total = 0
    unmatched_ids = []
    for result in matches:
        if result["status"] == "matched":
            matched_count += 1
            net_total += result["amount"]
        else:
            unmatched_ids.append(result["order_id"])
    unmatched_ids.sort()
    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Parse a string amount into an integer number of cents."""
    try:
        # Convert the string to a Decimal, then to an integer in cents
        amount = Decimal(s.strip())
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    """Parse a single record line into a dictionary."""
    fields = line.strip().split('|')

    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = map(str.strip, fields)

    # Normalize type to uppercase
    record_type = record_type.upper()

    # Validate TYPE
    if record_type not in {"ORDER", "PAYMENT"}:
        return None

    # Validate RECORD_ID and ORDER_ID for ORDER type
    if record_type == "ORDER" and record_id != order_id:
        return None

    # Validate AMOUNT
    parsed_amount = parse_amount(amount)
    if parsed_amount is None:
        return None

    # Validate CURRENCY
    if currency != "USD":
        return None

    # Validate TIMESTAMP
    try:
        timestamp = datetime.strptime(timestamp, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": parsed_amount,
        "currency": currency,
        "timestamp": timestamp
    }


def load_records(text):
    """Parse all lines of text into a list of record dictionaries."""
    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and not any(r['record_id'] == record['record_id'] for r in records):
            records.append(record)
    return records


def match_payments(records):
    """Match payments to orders based on order_id and timestamp criteria."""
    orders = []
    payments = []

    # Separate orders and payments
    for record in records:
        if record["type"] == "ORDER":
            orders.append(record)
        elif record["type"] == "PAYMENT" and record["amount"] >= 0:
            payments.append(record)

    results = []

    for order in orders:
        order_id = order["order_id"]
        order_timestamp = order["timestamp"]
        end_timestamp = order_timestamp + timedelta(hours=72)

        # Find qualifying payments
        qualifying_payments = [
            payment for payment in payments
            if payment["order_id"] == order_id and 
            order_timestamp <= payment["timestamp"] <= end_timestamp
        ]

        if qualifying_payments:
            # Sort by timestamp, then by original order
            qualifying_payments.sort(key=lambda p: (p["timestamp"], payments.index(p)))
            best_payment = qualifying_payments[0]
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": best_payment["amount"]
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0
            })

    return results


def compute_refunds(records):
    """Compute the total amount of refunds from the records."""
    refund_total = sum(
        record["amount"] for record in records 
        if record["type"] == "PAYMENT" and record["amount"] < 0
    )
    return refund_total


def build_summary(matches, refund_total):
    """Build a summary report from matched results and total refunds."""
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched')
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'] != 'matched')

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids
    }

