from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Convert the string amount to a Decimal, then to an integer in cents
        amount = Decimal(s.strip())
        return int(amount * 100)  # Convert dollars to cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')

    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_str, currency, timestamp_str = map(str.strip, fields)

    # Normalize type to uppercase
    record_type = record_type.upper()

    # Validate TYPE
    if record_type not in {"ORDER", "PAYMENT"}:
        return None

    # Validate RECORD_ID and ORDER_ID for ORDER type
    if record_type == "ORDER" and record_id != order_id:
        return None

    # Validate non-empty identifiers
    if not record_id or not order_id:
        return None

    # Parse amount
    amount = parse_amount(amount_str)
    if amount is None:
        return None

    # Validate currency
    if currency != "USD":
        return None

    # Validate timestamp
    try:
        timestamp = datetime.strptime(timestamp_str, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp
    }


def load_records(text):
    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and not any(r['record_id'] == record['record_id'] for r in records):
            records.append(record)
    return records


def match_payments(records):
    orders = {}
    payments = []

    # Separate orders and payments
    for record in records:
        if record["type"] == "ORDER":
            orders[record["order_id"]] = record
        elif record["type"] == "PAYMENT":
            payments.append(record)

    results = []

    for order_id, order in orders.items():
        order_timestamp = order["timestamp"]
        order_amount = order["amount"]
        matching_payment = None

        # Find eligible payments
        for payment in payments:
            if (payment["order_id"] == order_id and 
                order_timestamp <= payment["timestamp"] <= order_timestamp + timedelta(hours=72) and 
                payment["amount"] >= 0):

                if matching_payment is None or payment["timestamp"] < matching_payment["timestamp"]:
                    matching_payment = payment

        if matching_payment:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": matching_payment["amount"]
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0
            })

    return results


def compute_refunds(records):
    refund_total = 0

    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            refund_total += -record["amount"]  # Subtracting because amount is negative

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched')

    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'] != 'matched')

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids
    }

