"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s.strip())
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_str, currency, timestamp_str = fields
    record_type = record_type.strip().upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    currency = currency.strip()

    if not record_id or not order_id or currency != 'USD':
        return None

    if record_type == 'ORDER' and record_id != order_id:
        return None

    if record_type == 'PAYMENT' and record_id != order_id:
        return None

    amount = parse_amount(amount_str)
    if amount is None:
        return None

    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    lines = text.strip().splitlines()
    records = []
    for line in lines:
        record = parse_record(line)
        if record:
            records.append(record)
    return records


def match_payments(records):
    matches = []
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = sorted(
        [record for record in records if record['type'] == 'PAYMENT'],
        key=lambda x: x['timestamp']
    )

    for order in orders:
        order_id = order['order_id']
        order_timestamp = order['timestamp']
        matched_payment = None

        for payment in payments:
            if (payment['order_id'] == order_id and
                order_timestamp <= payment['timestamp'] <= order_timestamp + timedelta(hours=72) and
                payment['amount'] >= 0):
                matched_payment = payment
                break

        if matched_payment:
            matches.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': matched_payment['amount']
            })
        else:
            matches.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return matches


def compute_refunds(records):
    raise NotImplementedError


def build_summary(matches, refund_total):
    total_orders = 0
    matched_count = 0
    net_total = 0
    unmatched_ids = set()

    for match in matches:
        if match['status'] == 'matched':
            matched_count += 1
            net_total += match['amount']
        else:
            unmatched_ids.add(match['order_id'])

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'net_total': net_total - refund_total,
        'unmatched_ids': sorted(unmatched_ids)
    }

