    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id:
        return None
    if record_type == 'ORDER' and record_id != order_id:
        return None

    if currency.strip() != 'USD':
        return None

    parsed_amount = parse_amount(amount)
    if parsed_amount is None:
        return None

    try:
        parsed_timestamp = datetime.strptime(timestamp.strip(), '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': parsed_amount,
        'currency': currency.strip(),
        'timestamp': parsed_timestamp
    }


def load_records(text):
    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    orders = {}
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = record
        elif record['type'] == 'PAYMENT':
            payments.append(record)

    results = []

    for order_id, order in orders.items():
        matched_payment = None
        order_timestamp = order['timestamp']

        for payment in payments:
            if payment['amount'] < 0:  # Skip refunds
                continue
            if order_timestamp <= payment['timestamp'] <= order_timestamp + timedelta(hours=72):
                if matched_payment is None or payment['timestamp'] < matched_payment['timestamp']:
                    matched_payment = payment

        if matched_payment:
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': matched_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    raise NotImplementedError


