            matched_count += 1
            net_total += match['amount']

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'net_total': net_total,
        'unmatched_ids': sorted(unmatched_ids)
    }

"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or s == "":
        return None

    text = s
    if text.startswith("-"):
        text = text[1:]

    if text == "":
        return None

    decimal_points = 0
    digit_count = 0
    fractional_digits = 0
    after_decimal = False

    for char in text:
        if "0" <= char <= "9":
            digit_count += 1
            if after_decimal:
                fractional_digits += 1
        elif char == "." and decimal_points == 0:
            decimal_points += 1
            after_decimal = True
        else:
            return None

    if digit_count == 0 or fractional_digits > 3:
        return None

    try:
        amount = Decimal(s).quantize(
            Decimal("0.01"),
            rounding=ROUND_HALF_UP,
        )
        return int(amount * 100)
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields

    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id:
        return None

    if record_type == "ORDER" and record_id != order_id:
        return None

    currency = currency.strip()
    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    if (
        len(timestamp_text) != 16
        or timestamp_text[4] != "-"
        or timestamp_text[7] != "-"
        or timestamp_text[10] != " "
        or timestamp_text[13] != ":"
    ):
        return None

    for index, char in enumerate(timestamp_text):
        if index not in (4, 7, 10, 13) and not char.isdigit():
            return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        try:
            record = parse_record(line)
        except Exception:
            record = None

        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append({
            "type": record["type"],
            "record_id": record["record_id"],
            "order_id": record["order_id"],
            "amount": record["amount"],
            "currency": record["currency"],
            "timestamp": record["timestamp"],
        })

    return records


def match_payments(records):
    results = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        order_timestamp = order["timestamp"]
        latest_timestamp = order_timestamp + timedelta(hours=72)
        best_payment = None

        for payment in records:
            if payment["type"] != "PAYMENT":
                continue
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["amount"] < 0:
                continue
            if payment["timestamp"] < order_timestamp:
                continue
            if payment["timestamp"] > latest_timestamp:
                continue

            if (
                best_payment is None
                or payment["timestamp"] < best_payment["timestamp"]
            ):
                best_payment = payment

        if best_payment is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": best_payment["amount"],
            })

    return results


def compute_refunds(records):
    total = 0

    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += -record["amount"]

    return total


def build_summary(matches, refund_total):
    matched_total = 0
    unmatched_ids = []
    matched_count = 0

    for result in matches:
        if result["status"] == "matched":
            matched_count += 1
            matched_total += result["amount"]
        else:
            unmatched_ids.append(result["order_id"])

    unmatched_ids.sort()

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": matched_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

