"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        if not isinstance(s, str):
            return None
        text = s.strip()
        if not text:
            return None
        signless = text[1:] if text.startswith("-") else text
        if not signless or signless.count(".") > 1:
            return None
        if any(not (ch.isdigit() or ch == ".") for ch in signless):
            return None
        if not any(ch.isdigit() for ch in signless):
            return None
        if "." in signless and len(signless.split(".", 1)[1]) > 3:
            return None
        value = Decimal(text)
        if not value.is_finite():
            return None
        cents = (value * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        )
        return int(cents)
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None


def parse_record(line):
    try:
        if not isinstance(line, str):
            return None
        fields = line.split("|")
        if len(fields) != 6:
            return None
        kind = fields[0].strip().upper()
        record_id = fields[1].strip()
        order_id = fields[2].strip()
        currency = fields[4].strip()
        if kind not in ("ORDER", "PAYMENT"):
            return None
        if not record_id or not order_id or currency != "USD":
            return None
        if kind == "ORDER" and record_id != order_id:
            return None
        amount = parse_amount(fields[3])
        if amount is None or (kind == "ORDER" and amount < 0):
            return None
        timestamp_text = fields[5]
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
        if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
            return None
        return {
            "type": kind,
            "record_id": record_id,
            "order_id": order_id,
            "amount": amount,
            "currency": "USD",
            "timestamp": timestamp,
        }
    except (ValueError, TypeError, OverflowError):
        return None


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            records.append(record)
    return records


def match_payments(records):
    orders = []
    payments = []
    for record in records:
        if record.get("type") == "ORDER":
            orders.append(record)
        elif record.get("type") == "PAYMENT":
            payments.append(record)

    results = []
    for order in orders:
        order_time = order["timestamp"]
        latest_time = order_time + timedelta(hours=72)
        chosen = None
        for payment in payments:
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["amount"] < 0:
                continue
            payment_time = payment["timestamp"]
            if order_time <= payment_time <= latest_time:
                if chosen is None or payment_time < chosen["timestamp"]:
                    chosen = payment
        if chosen is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": chosen["amount"],
            })
    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if record.get("type") == "PAYMENT" and record.get("amount", 0) < 0:
            total += -record["amount"]
    return total


def build_summary(matches, refund_total):
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for result in matches:
        if result.get("status") == "matched":
            matched_count += 1
            net_total += result.get("amount", 0)
        else:
            unmatched_ids.append(result.get("order_id"))

    unmatched_ids.sort()
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

