"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None
    sign = 1
    if s[0] == "-":
        sign = -1
        s = s[1:]
    if not s or s.count(".") > 1:
        return None
    parts = s.split(".")
    whole = parts[0]
    fraction = parts[1] if len(parts) == 2 else ""
    if not whole and not fraction:
        return None
    if not all(ch.isdigit() for ch in whole + fraction):
        return None
    if len(fraction) > 3:
        return None
    whole_value = int(whole) if whole else 0
    padded = fraction.ljust(3, "0")
    cents = whole_value * 100 + int(padded[:2])
    if int(padded[2]) >= 5:
        cents += 1
    return sign * cents


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    currency = currency.strip()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id or currency != "USD":
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    amount = parse_amount(amount_text)
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None
    if (
        len(timestamp_text) != 16
        or timestamp_text[4] != "-"
        or timestamp_text[7] != "-"
        or timestamp_text[10] != " "
        or timestamp_text[13] != ":"
        or not (
            timestamp_text[:4].isdigit()
            and timestamp_text[5:7].isdigit()
            and timestamp_text[8:10].isdigit()
            and timestamp_text[11:13].isdigit()
            and timestamp_text[14:16].isdigit()
        )
    ):
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (ValueError, TypeError):
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen_ids = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue
        record_id = record["record_id"]
        if record_id in seen_ids:
            continue
        seen_ids.add(record_id)
        records.append(record)
    return records


def match_payments(records):
    results = []
    for order in records:
        if order["type"] != "ORDER":
            continue
        order_time = order["timestamp"]
        latest = order_time + timedelta(hours=72)
        selected = None
        for payment in records:
            if payment["type"] != "PAYMENT":
                continue
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["amount"] < 0:
                continue
            payment_time = payment["timestamp"]
            if order_time <= payment_time <= latest:
                if selected is None or payment_time < selected["timestamp"]:
                    selected = payment
        if selected is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": selected["amount"],
            })
    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += -record["amount"]
    return total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for match in matches:
        if match["status"] == "matched":
            matched_count += 1
            net_total += match["amount"]
        else:
            unmatched_ids.append(match["order_id"])

    unmatched_ids.sort()
    net_total -= refund_total

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids,
    }

"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Convert the string amount to a Decimal and then to an integer in cents
        amount = Decimal(s.strip())
        return int(amount * 100)  # Convert to cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_str, currency, timestamp_str = map(str.strip, fields)

    # Normalize type to uppercase
    record_type = record_type.upper()

    # Validate TYPE
    if record_type not in {"ORDER", "PAYMENT"}:
        return None

    # Validate RECORD_ID and ORDER_ID for ORDER type
    if record_type == "ORDER" and record_id != order_id:
        return None

    # Validate AMOUNT
    amount = parse_amount(amount_str)
    if amount is None:
        return None

    # Validate CURRENCY
    if currency != "USD":
        return None

    # Validate TIMESTAMP
    try:
        timestamp = datetime.strptime(timestamp_str, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp
    }


def load_records(text):
    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and all(r['record_id'] != record['record_id'] for r in records):
            records.append(record)
    return records


def match_payments(records):
    orders = []
    payments = []

    # Separate orders and payments
    for record in records:
        if record["type"] == "ORDER":
            orders.append(record)
        elif record["type"] == "PAYMENT":
            payments.append(record)

    results = []

    for order in orders:
        order_id = order["order_id"]
        order_timestamp = order["timestamp"]
        order_amount = order["amount"]

        # Find qualifying payments
        qualifying_payments = [
            payment for payment in payments
            if payment["order_id"] == order_id and
            payment["amount"] >= 0 and
            order_timestamp <= payment["timestamp"] <= order_timestamp + timedelta(hours=72)
        ]

        if qualifying_payments:
            # Sort by timestamp, then by original order
            qualifying_payments.sort(key=lambda p: (p["timestamp"], payments.index(p)))
            matched_payment = qualifying_payments[0]
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": matched_payment["amount"]
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0
            })

    return results


def compute_refunds(records):
    refunds = []
    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            refunds.append(record["amount"])
    refund_total = sum(refunds)
    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched')
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'] != 'matched')

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids
    }

