"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    s = s.strip()
    try:
        amount = Decimal(s) * 100
        return int(amount.to_integral_value(rounding=ROUND_HALF_UP))
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = map(str.strip, fields)

    if record_type.upper() not in ['ORDER', 'PAYMENT']:
        return None
    if record_id == '' or order_id == '':
        return None
    if record_type.upper() == 'ORDER' and record_id != order_id:
        return None

    try:
        amount = parse_amount(amount)
        if amount is None:
            return None
    except Exception:
        return None

    if currency != 'USD':
        return None

    try:
        timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type.upper(),
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    lines = text.strip().splitlines()
    records = []
    for line in lines:
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = [record for record in records if record['type'] == 'PAYMENT']
    results = []

