from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None

    text = s
    if text.startswith("-"):
        text = text[1:]

    if not text or any(character not in "0123456789." for character in text):
        return None
    if text.count(".") > 1:
        return None

    whole, separator, fraction = text.partition(".")
    if not whole and not fraction:
        return None
    if len(fraction) > 3:
        return None

    try:
        value = Decimal(s)
        cents = (value * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        )
        return int(cents)
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type = fields[0]
    if record_type.upper() not in ("ORDER", "PAYMENT"):
        return None
    record_type = record_type.upper()

    record_id = fields[1].strip()
    order_id = fields[2].strip()
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None

    currency = fields[4].strip()
    if currency != "USD":
        return None

    amount = parse_amount(fields[3])
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    timestamp_text = fields[5]
    if (
        len(timestamp_text) != 16
        or timestamp_text[4] != "-"
        or timestamp_text[7] != "-"
        or timestamp_text[10] != " "
        or timestamp_text[13] != ":"
        or not all(
            timestamp_text[index].isdigit()
            for index in (0, 1, 2, 3, 5, 6, 8, 9, 11, 12, 14, 15)
        )
    ):
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
