    negative = False
    if s[0] == "-":
        negative = True
        s = s[1:]

    if not s:
        return None

    if s.count(".") > 1:
        return None

    if "." in s:
        whole_text, fraction_text = s.split(".")
        if not whole_text and not fraction_text:
            return None
        if len(fraction_text) > 3:
            return None
    else:
        whole_text = s
        fraction_text = ""

    if any(character not in "0123456789" for character in whole_text):
        return None
    if any(character not in "0123456789" for character in fraction_text):
        return None

    whole = 0
    for character in whole_text:
        whole = whole * 10 + (ord(character) - ord("0"))

    fraction = fraction_text.ljust(3, "0")
    cents = whole * 100
    if fraction:
        cents += (ord(fraction[0]) - ord("0")) * 10
        cents += ord(fraction[1]) - ord("0")
        if fraction[2] >= "5":
            cents += 1

    if negative:
        cents = -cents

    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields

    if record_type not in ("ORDER", "PAYMENT", "order", "payment"):
        return None
    record_type = record_type.upper()

    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id:
        return None

    if record_type == "ORDER" and record_id != order_id:
        return None

    currency = currency.strip()
    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    if len(timestamp_text) != 16:
        return None

    digit_positions = (
        0, 1, 2, 3, 5, 6, 8, 9, 11, 12, 14, 15
    )
    for position in digit_positions:
        if timestamp_text[position] not in "0123456789":
            return None

    if timestamp_text[4] != "-" or timestamp_text[7] != "-":
        return None
    if timestamp_text[10] != " " or timestamp_text[13] != ":":
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None

    if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
