    results = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        order_id = order["order_id"]
        order_time = order["timestamp"]
        latest_time = order_time + timedelta(hours=72)

        chosen_payment = None

        for payment in records:
            if payment["type"] != "PAYMENT":
                continue
            if payment["order_id"] != order_id:
                continue
            if payment["amount"] < 0:
                continue

            payment_time = payment["timestamp"]
            if payment_time < order_time or payment_time > latest_time:
                continue

            if (
                chosen_payment is None
                or payment_time < chosen_payment["timestamp"]
            ):
                chosen_payment = payment

        if chosen_payment is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": chosen_payment["amount"],
            })

    return results


def compute_refunds(records):
    total = 0

    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += -record["amount"]

    return total


