"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    text = s.strip()
    if not text:
        return None
    negative = text.startswith("-")
    if negative:
        text = text[1:]
    if not text or text.count(".") > 1:
        return None
    if "." in text:
        whole, fraction = text.split(".")
    else:
        whole, fraction = text, ""
    if not whole and not fraction:
        return None
    if whole and not whole.isdigit():
        return None
    if fraction and not fraction.isdigit():
        return None
    if len(fraction) > 3:
        return None
    value = int(whole or "0") * 100
    value += int((fraction + "00")[:2])
    if len(fraction) == 3 and fraction[2] >= "5":
        value += 1
    return -value if negative else value


def parse_record(line):
    if not isinstance(line, str):
        return None
    parts = line.split("|")
    if len(parts) != 6:
        return None
    record_type, record_id, order_id, amount_text, currency, timestamp_text = (
        part.strip() for part in parts
    )
    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id or currency != "USD":
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    amount = parse_amount(amount_text)
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None
    if len(timestamp_text) != 16:
        return None
    if (timestamp_text[4] != "-" or timestamp_text[7] != "-" or
            timestamp_text[10] != " " or timestamp_text[13] != ":"):
        return None
    digits = timestamp_text[:4] + timestamp_text[5:7] + timestamp_text[8:10]
    digits += timestamp_text[11:13] + timestamp_text[14:16]
    if not digits.isdigit():
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is None or record["record_id"] in seen:
            continue
        seen.add(record["record_id"])
        records.append(record)
    return records


def match_payments(records):
    orders = [record for record in records if record["type"] == "ORDER"]
    payments = [record for record in records if record["type"] == "PAYMENT"]
    results = []
    for order in orders:
        best = None
        deadline = order["timestamp"] + timedelta(hours=72)
        for payment in payments:
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["amount"] < 0:
                continue
            if order["timestamp"] <= payment["timestamp"] <= deadline:
                if best is None or payment["timestamp"] < best["timestamp"]:
                    best = payment
        if best is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": best["amount"],
            })
    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += -record["amount"]
    return total


def build_summary(matches, refund_total):
    matched_count = 0
    net_total = -refund_total
    unmatched_ids = []
    for result in matches:
        if result["status"] == "matched":
            matched_count += 1
            net_total += result["amount"]
        elif result["status"] == "unmatched":
            unmatched_ids.append(result["order_id"])
    unmatched_ids.sort()
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids,
    }

