from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a strict decimal monetary value to integer cents."""
    if not isinstance(s, str) or not s:
        return None

    value = s
    if value.startswith("-"):
        digits = value[1:]
    else:
        digits = value

    if digits.count(".") > 1:
        return None

    if "." in digits:
        whole, fraction = digits.split(".")
        if not whole or not fraction:
            return None
        if not whole.isdigit() or not fraction.isdigit():
            return None
        if len(fraction) > 3:
            return None
    else:
        whole, fraction = digits, ""
        if not whole.isdigit():
            return None

    try:
        amount = Decimal(value).quantize(
            Decimal("0.01"), rounding=ROUND_HALF_UP
        )
        if not amount.is_finite():
            return None
        return int(amount * 100)
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    """Parse one input line into a validated record dictionary."""
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    if (
