def load_records(text):
    """Load valid records, retaining only the first valid record ID."""
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen_ids:
            seen_ids.add(record["record_id"])
            records.append(record)

    return records


def match_payments(records):
    """Return the earliest qualifying payment for each order."""
    orders = []
    payments_by_order = {}

    for record in records:
        if record["type"] == "ORDER":
            orders.append(record)
        elif record["type"] == "PAYMENT":
            if record["amount"] < 0:
                continue
            payments_by_order.setdefault(record["order_id"], []).append(record)

    results = []

    for order in orders:
        order_id = order["order_id"]
        order_time = order["timestamp"]
        latest_time = order_time + timedelta(hours=72)
        best_payment = None

        for payment in payments_by_order.get(order_id, []):
            payment_time = payment["timestamp"]
            if order_time <= payment_time <= latest_time:
                if (
                    best_payment is None
                    or payment_time < best_payment["timestamp"]
                ):
                    best_payment = payment

        if best_payment is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": best_payment["amount"],
            })

    return results


def compute_refunds(records):
    """Return the total refund amount in cents."""
    total = 0

    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += abs(record["amount"])

    return total


def build_summary(matches, refund_total):
    """Build a summary from match results."""
    matched = [
        result for result in matches
        if result["status"] == "matched"
    ]
    unmatched_ids = [
        result["order_id"] for result in matches
        if result["status"] != "matched"
    ]

    return {
        "total_orders": len(matches),
        "matched_count": len(matched),
        "net_total": sum(result["amount"] for result in matched) - refund_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

