from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a decimal amount to integer cents, or return None if invalid."""
    if not isinstance(s, str):
        return None

    value = s.strip()
    if not value:
        return None

    negative = value.startswith("-")
    if negative:
        value = value[1:]

    if value.count(".") > 1:
        return None

    whole, dot, fraction = value.partition(".")
    if not whole and not fraction:
        return None
    if whole and not all("0" <= ch <= "9" for ch in whole):
        return None
    if fraction and not all("0" <= ch <= "9" for ch in fraction):
        return None
    if len(fraction) > 3:
        return None

    cents = int(whole or "0") * 100
    cents += int((fraction + "00")[:2])

    if len(fraction) == 3 and fraction[2] >= "5":
        cents += 1

    return -cents if negative else cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type = fields[0].strip().upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(fields[3])
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None

    if fields[4] != "USD":
        return None

    timestamp_text = fields[5]
    if (
        len(timestamp_text) != 16
        or timestamp_text[4] != "-"
        or timestamp_text[7] != "-"
        or timestamp_text[10] != " "
        or timestamp_text[13] != ":"
        or not all(
            timestamp_text[i].isdigit()
            for i in (0, 1, 2, 3, 5, 6, 8, 9, 11, 12, 14, 15)
        )
    ):
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": "USD",
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    seen = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None or record["record_id"] in seen:
            continue
        seen.add(record["record_id"])
        records.append(record)

    return records


def match_payments(records):
    if not isinstance(records, list):
        return []

    orders = []
    payments = []

    for record in records:
        if not isinstance(record, dict):
            continue

        record_type = record.get("type")
        if record_type == "ORDER":
            orders.append(record)
        elif record_type == "PAYMENT":
            amount = record.get("amount")
            if isinstance(amount, int) and amount >= 0:
                payments.append(record)

    results = []

    for order in orders:
        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        best_payment = None

        if isinstance(order_id, str) and isinstance(order_time, datetime):
            latest_time = order_time + timedelta(hours=72)

            for payment in payments:
                if payment.get("order_id") != order_id:
                    continue

                payment_time = payment.get("timestamp")
                if not isinstance(payment_time, datetime):
                    continue

                if order_time <= payment_time <= latest_time:
                    if (
                        best_payment is None
                        or payment_time < best_payment.get("timestamp")
                    ):
                        best_payment = payment

        if best_payment is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": best_payment["amount"],
            })

    return results


def compute_refunds(records):
    """Return the total absolute value of all negative payment amounts."""
    if not isinstance(records, list):
        return 0

    refund_total = 0

    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue

        amount = record.get("amount")
        if isinstance(amount, int) and amount < 0:
            refund_total += -amount

    return refund_total


def build_summary(matches, refund_total):
    """Build the four-field summary for matched and unmatched orders."""
    if not isinstance(matches, list):
        matches = []

    matched_count = 0
    matched_total = 0
    unmatched_ids = []

    for result in matches:
        if not isinstance(result, dict):
            continue

        if result.get("status") == "matched":
            matched_count += 1
            amount = result.get("amount", 0)
            if isinstance(amount, int):
                matched_total += amount
        elif result.get("status") == "unmatched":
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.append(order_id)

    if isinstance(refund_total, int) and refund_total > 0:
        net_total = matched_total - refund_total
    else:
        net_total = matched_total

    unmatched_ids.sort()

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids,
    }

