from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Convert the string amount to a Decimal, then to an integer in cents
        amount = Decimal(s.strip())
        return int(amount * 100)  # Convert dollars to cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_str, currency, timestamp_str = map(str.strip, fields)

    # Normalize type to uppercase
    record_type = record_type.upper()

    # Validate TYPE
    if record_type not in {"ORDER", "PAYMENT"}:
        return None

    # Validate RECORD_ID and ORDER_ID for ORDER type
    if record_type == "ORDER" and record_id != order_id:
        return None

    # Validate AMOUNT
    amount = parse_amount(amount_str)
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None

    # Validate CURRENCY
    if currency != "USD":
        return None

    # Validate TIMESTAMP
    try:
        timestamp = datetime.strptime(timestamp_str, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    # Create the record dictionary
    record = {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp
    }

    return record


def load_records(text):
    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and all(r["record_id"] != record["record_id"] for r in records):
            records.append(record)
    return records


def match_payments(records):
    orders = []
    payments = []

    for record in records:
        if record["type"] == "ORDER":
            orders.append(record)
        elif record["type"] == "PAYMENT" and record["amount"] >= 0:
            payments.append(record)

    results = []

    for order in orders:
        order_id = order["order_id"]
        order_timestamp = order["timestamp"]
        end_time = order_timestamp + timedelta(hours=72)

        # Filter payments that qualify for this order
        qualifying_payments = [
            payment for payment in payments
            if payment["order_id"] == order_id and 
            order_timestamp <= payment["timestamp"] <= end_time
        ]

        if qualifying_payments:
            # Sort by timestamp, then by original order
            qualifying_payments.sort(key=lambda p: (p["timestamp"], payments.index(p)))
            matched_payment = qualifying_payments[0]
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": matched_payment["amount"]
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0
            })

    return results


def compute_refunds(records):
    refund_total = 0

    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            refund_total += -record["amount"]  # Subtracting the negative amount

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched')

    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'] != 'matched')

    summary = {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids
    }

    return summary

