        return None

    if type_value == "ORDER" and amount < 0:
        return None

    timestamp_text = fields[5]
    if (
        len(timestamp_text) != 16
        or timestamp_text[4] != "-"
        or timestamp_text[7] != "-"
        or timestamp_text[10] != " "
        or timestamp_text[13] != ":"
    ):
        return None

    digit_positions = (
        list(range(0, 4))
        + list(range(5, 7))
        + list(range(8, 10))
        + list(range(11, 13))
        + list(range(14, 16))
    )
    if any(not timestamp_text[index].isdigit() for index in digit_positions):
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": type_value,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    seen_record_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"].strip()
        if record_id in seen_record_ids:
            continue

        seen_record_ids.add(record_id)
        records.append({
            "type": record["type"],
            "record_id": record_id,
            "order_id": record["order_id"],
            "amount": record["amount"],
            "currency": record["currency"],
            "timestamp": record["timestamp"],
        })

    return records


def match_payments(records):
    results = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        order_id = order["order_id"]
        order_time = order["timestamp"]
        latest_time = order_time + timedelta(hours=72)
        chosen_payment = None
        chosen_key = None

        for source_index, payment in enumerate(records):
            if payment["type"] != "PAYMENT":
                continue
            if payment["order_id"] != order_id:
                continue
            if payment["amount"] < 0:
                continue

            payment_time = payment["timestamp"]
            if payment_time < order_time or payment_time > latest_time:
                continue

            candidate_key = (payment_time, source_index)
            if chosen_key is None or candidate_key < chosen_key:
                chosen_key = candidate_key
                chosen_payment = payment

        if chosen_payment is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": chosen_payment["amount"],
            })

    return results


def compute_refunds(records):
    total = 0

    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += abs(record["amount"])

    return total


def build_summary(matches, refund_total):
    matched_count = 0
    matched_total = 0
    unmatched_ids = []

    for result in matches:
        if result["status"] == "matched":
            matched_count += 1
            matched_total += result["amount"]
        else:
            unmatched_ids.append(result["order_id"])

    unmatched_ids.sort()

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": matched_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a string representation of a monetary amount to an integer in cents."""
    try:
        # Convert the string to a Decimal and then to an integer in cents
        amount = Decimal(s.strip())
        return int(amount * 100)  # Convert dollars to cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    """Parse a single record line into a dictionary."""
    fields = line.strip().split('|')

    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_str, currency, timestamp_str = map(str.strip, fields)

    # Normalize type to uppercase
    record_type = record_type.upper()

    # Validate TYPE
    if record_type not in {"ORDER", "PAYMENT"}:
        return None

    # Validate RECORD_ID and ORDER_ID for ORDER type
    if record_type == "ORDER" and record_id != order_id:
        return None

    # Validate non-empty identifiers
    if not record_id or not order_id:
        return None

    # Parse amount
    amount = parse_amount(amount_str)
    if amount is None:
        return None

    # Validate currency
    if currency != "USD":
        return None

    # Validate timestamp format
    try:
        timestamp = datetime.strptime(timestamp_str, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp
    }


def load_records(text):
    """Parse multiple lines of text into a list of record dictionaries."""
    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and not any(r['record_id'] == record['record_id'] for r in records):
            records.append(record)
    return records


def match_payments(records):
    """Match payments to orders based on order_id and timestamp criteria."""
    orders = []
    payments = []

    for record in records:
        if record["type"] == "ORDER":
            orders.append(record)
        elif record["type"] == "PAYMENT" and record["amount"] >= 0:
            payments.append(record)

    results = []

    for order in orders:
        order_id = order["order_id"]
        order_timestamp = order["timestamp"]
        end_timestamp = order_timestamp + timedelta(hours=72)

        # Filter payments that qualify for this order
        qualifying_payments = [
            payment for payment in payments
            if payment["order_id"] == order_id and 
            order_timestamp <= payment["timestamp"] <= end_timestamp
        ]

        if qualifying_payments:
            # Sort by timestamp, then by original order
            qualifying_payments.sort(key=lambda p: (p["timestamp"], payments.index(p)))
            best_payment = qualifying_payments[0]
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": best_payment["amount"]
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0
            })

    return results


def compute_refunds(records):
    """Compute the total refunds from the records."""
    total_refunds = 0

    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total_refunds += -record["amount"]  # Subtracting a negative amount to get a positive refund total

    return total_refunds


def build_summary(matches, refund_total):
    """Build a summary report from matched results and total refunds."""
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched')
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'] == 'unmatched')

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids
    }

"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a decimal amount to integer cents, or return None."""
    import re

    if not isinstance(s, str):
        return None

    value = s.strip()
    if not re.fullmatch(r"-?\d+(?:\.\d{1,3})?", value):
        return None

    try:
        amount = Decimal(value)
        cents = (amount * Decimal("100")).quantize(
            Decimal("1"),
            rounding=ROUND_HALF_UP,
        )
    except (InvalidOperation, ValueError):
        return None

    return int(cents)


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None

    if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": "USD",
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue
        if record["record_id"] in seen_ids:
            continue
        seen_ids.add(record["record_id"])
        records.append(record)

    return records


def match_payments(records):
    """Match each order with its earliest qualifying payment."""
    results = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        best_payment = None
        deadline = order["timestamp"] + timedelta(hours=72)

        for payment in records:
            if payment["type"] != "PAYMENT":
                continue
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["amount"] < 0:
                continue
            if payment["timestamp"] < order["timestamp"]:
                continue
            if payment["timestamp"] > deadline:
                continue

            if (
                best_payment is None
                or payment["timestamp"] < best_payment["timestamp"]
            ):
                best_payment = payment

        if best_payment is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": best_payment["amount"],
            })

    return results


def compute_refunds(records):
    """Return the total absolute value of negative payment amounts in cents."""
    refund_total = 0

    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            refund_total += abs(record["amount"])

    return refund_total


def build_summary(matches, refund_total):
    """Build a summary of payment matching results."""
    matched_count = 0
    matched_total = 0
    unmatched_ids = []

    for result in matches:
        if result["status"] == "matched":
            matched_count += 1
            matched_total += result["amount"]
        elif result["status"] == "unmatched":
            unmatched_ids.append(result["order_id"])

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": matched_total - refund_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

