    record_type, record_id, order_id, amount_str, currency, timestamp_str = map(str.strip, fields)

    # Normalize type to uppercase
    record_type = record_type.upper()

    # Validate TYPE
    if record_type not in {"ORDER", "PAYMENT"}:
        return None

    # Validate RECORD_ID and ORDER_ID for ORDER type
    if record_type == "ORDER":
        if record_id != order_id:
            return None

    # Validate AMOUNT
    amount = parse_amount(amount_str)
    if amount is None:
        return None

    # Validate CURRENCY
    if currency != "USD":
        return None

    # Validate TIMESTAMP
    try:
        timestamp = datetime.strptime(timestamp_str, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp
    }


def load_records(text):
    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and not any(r['record_id'] == record['record_id'] for r in records):
            records.append(record)
    return records


