    }

"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a valid decimal monetary string to integer cents."""
    if not isinstance(s, str):
        return None

    text = s.strip()
    if not re.fullmatch(r"-?\d+(?:\.\d{1,3})?", text):
        return None

    try:
        value = Decimal(text)
        if not value.is_finite():
            return None
        return int(
            (value * Decimal("100")).quantize(
                Decimal("1"),
                rounding=ROUND_HALF_UP,
            )
        )
    except (InvalidOperation, ValueError, TypeError):
        return None


def parse_record(line):
    """Parse one input record and return a dictionary, or None if invalid."""
    if not isinstance(line, str):
        return None

    parts = line.split("|")
    if len(parts) != 6:
        return None

    record_type = parts[0].strip().upper()
    record_id = parts[1].strip()
    order_id = parts[2].strip()
    amount_text = parts[3]
    currency = parts[4].strip()
    timestamp_text = parts[5]

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    if not re.fullmatch(r"\d{4}-\d{2}-\d{2} \d{2}:\d{2}", timestamp_text):
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    """Parse valid records, keeping only the first valid occurrence of each ID."""
    if not isinstance(text, str):
        return []

    records = []
    seen_record_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_record_ids:
            continue

        seen_record_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    """Match each order with its earliest qualifying non-refund payment."""
    payments_by_order = {}

    for record in records:
        if record["type"] != "PAYMENT":
            continue
        if record["amount"] < 0:
            continue

        payments_by_order.setdefault(record["order_id"], []).append(record)

    results = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        order_time = order["timestamp"]
        latest_time = order_time + timedelta(hours=72)
        best_payment = None

        for payment in payments_by_order.get(order["order_id"], []):
            payment_time = payment["timestamp"]

            if order_time <= payment_time <= latest_time:
                if (
                    best_payment is None
                    or payment_time < best_payment["timestamp"]
                ):
                    best_payment = payment

        if best_payment is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": best_payment["amount"],
            })

    return results


def compute_refunds(records):
    """Return the total absolute value of all negative payment amounts."""
    total = 0

    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += abs(record["amount"])

    return total


def build_summary(matches, refund_total):
    """Build a summary of matched and unmatched orders."""
    matched_count = 0
    matched_total = 0
    unmatched_ids = []

    for result in matches:
        if result["status"] == "matched":
            matched_count += 1
            matched_total += result["amount"]
        else:
            unmatched_ids.append(result["order_id"])

    unmatched_ids.sort()

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": matched_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

