"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Parse a decimal monetary value into integer cents."""
    if not isinstance(s, str):
        return None
    value = s.strip()
    if not value:
        return None
    import re
    if re.fullmatch(r"-?\d+(?:\.\d{0,3})?", value) is None:
        return None
    try:
        amount = Decimal(value)
        cents = amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        return int(cents * 100)
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None


def parse_record(line):
    """Parse one input line, returning a record or None when unsupported."""
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
    record_type = fields[0].strip().upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    amount_text = fields[3].strip()
    currency = fields[4].strip()
    timestamp_text = fields[5].strip()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    if currency != "USD":
        return None
    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None
    import re
    if re.fullmatch(r"\d{4}-\d{2}-\d{2} \d{2}:\d{2}", timestamp_text) is None:
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (ValueError, TypeError):
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": "USD",
        "timestamp": timestamp,
    }


def load_records(text):
    """Parse all lines, skipping invalid records and later duplicates."""
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            records.append(record)
    return records


def match_payments(records):
    """Return the earliest qualifying payment for each order."""
    if not isinstance(records, list):
        return []
    orders = [r for r in records
              if isinstance(r, dict) and r.get("type") == "ORDER"]
    payments = [r for r in records
                if isinstance(r, dict) and r.get("type") == "PAYMENT"]
    results = []
    window = timedelta(hours=72)
    for order in orders:
        qualifying = []
        for position, payment in enumerate(payments):
            if payment.get("order_id") != order.get("order_id"):
                continue
            amount = payment.get("amount")
            timestamp = payment.get("timestamp")
            order_time = order.get("timestamp")
            if not isinstance(amount, int) or amount < 0:
                continue
            if not isinstance(timestamp, datetime) or not isinstance(order_time, datetime):
                continue
            if order_time <= timestamp <= order_time + window:
                qualifying.append((timestamp, position, payment))
        if qualifying:
            qualifying.sort(key=lambda item: (item[0], item[1]))
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": qualifying[0][2]["amount"],
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
    return results


def compute_refunds(records):
    """Compute the positive total of negative payment amounts."""
    if not isinstance(records, list):
        return 0
    total = 0
    for record in records:
        if (isinstance(record, dict)
                and record.get("type") == "PAYMENT"
                and isinstance(record.get("amount"), int)
                and record["amount"] < 0):
            total += -record["amount"]
    return total


def build_summary(matches, refund_total):
    """Build summary totals and sorted unmatched order IDs."""
    if not isinstance(matches, list):
        matches = []
    total_orders = len(matches)
    matched_count = 0
    net_total = 0
    unmatched_ids = []
    for result in matches:
        if not isinstance(result, dict):
            continue
        if result.get("status") == "matched":
            matched_count += 1
            net_total += result.get("amount", 0)
        elif "order_id" in result:
            unmatched_ids.append(result["order_id"])
    unmatched_ids.sort()
    net_total -= refund_total
    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids,
    }

