from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Convert the string amount to a Decimal, then to an integer in cents
        amount = Decimal(s.strip())
        return int(amount * 100)  # Convert to cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_str, currency, timestamp_str = map(str.strip, fields)

    # Normalize type to uppercase
    record_type = record_type.upper()

    # Validate type
    if record_type not in {"ORDER", "PAYMENT"}:
        return None

    # Validate record_id and order_id
    if not record_id or not order_id or record_id != order_id:
        return None

    # Parse amount
    amount = parse_amount(amount_str)
    if amount is None:
        return None

    # Validate currency
    if currency != "USD":
        return None

    # Validate timestamp
    try:
        timestamp = datetime.strptime(timestamp_str, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp
    }


def load_records(text):
    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and all(r['record_id'] != record['record_id'] for r in records):
            records.append(record)
    return records


def match_payments(records):
    orders = []
    payments = []

    # Separate orders and payments
    for record in records:
        if record['type'] == 'ORDER':
            orders.append(record)
        elif record['type'] == 'PAYMENT':
            payments.append(record)

    results = []

    for order in orders:
        order_id = order['order_id']
        order_timestamp = order['timestamp']
        order_amount = order['amount']

        # Find eligible payments
        eligible_payments = [
            payment for payment in payments
            if payment['order_id'] == order_id and
            payment['amount'] >= 0 and
            order_timestamp <= payment['timestamp'] <= order_timestamp + timedelta(hours=72)
        ]

        if eligible_payments:
            # Sort by timestamp, then by original order
            eligible_payments.sort(key=lambda p: (p['timestamp'], payments.index(p)))
            matched_payment = eligible_payments[0]
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": matched_payment['amount']
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0
            })

    return results


def compute_refunds(records):
    refund_total = 0

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0:
            refund_total += abs(record['amount'])

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched')
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'] != 'matched')

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids
    }

