from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a valid monetary string to integer cents."""
    import re

    if not isinstance(s, str):
        return None

    value = s.strip()
    if re.fullmatch(r"[+-]?\d+(?:\.\d{1,4})?", value) is None:
        return None

    try:
        amount = Decimal(value)
        if not amount.is_finite():
            return None
        return int(
            (amount * Decimal("100")).quantize(
                Decimal("1"), rounding=ROUND_HALF_UP
            )
        )
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None

    import re

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()

    if record_type not in {"ORDER", "PAYMENT"}:
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None

    if re.fullmatch(r"\d{4}-\d{2}-\d{2} \d{2}:\d{2}", timestamp_text) is None:
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": "USD",
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    results = []

    if not isinstance(records, list):
        return results

    payments = [
        record
        for record in records
        if isinstance(record, dict)
        and record.get("type") == "PAYMENT"
        and record.get("amount", 0) >= 0
    ]

    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue

        order_id = order["order_id"]
        order_time = order["timestamp"]
        latest_time = order_time + timedelta(hours=72)

        best_payment = None

        for payment in payments:
            if payment.get("order_id") != order_id:
                continue

            payment_time = payment["timestamp"]
            if order_time <= payment_time <= latest_time:
                if (
                    best_payment is None
                    or payment_time < best_payment["timestamp"]
                ):
                    best_payment = payment

        if best_payment is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": best_payment["amount"],
            })

    return results


def compute_refunds(records):
    total = 0
    if not isinstance(records, list):
        return total

    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        amount = record.get("amount")
        if isinstance(amount, int) and amount < 0:
            total += abs(amount)

    return total


def build_summary(matches, refund_total):
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    if not isinstance(matches, list):
        matches = []

    for result in matches:
        if not isinstance(result, dict):
            continue

        if result.get("status") == "matched":
            matched_count += 1
            net_total += result.get("payment_amount", result.get("amount", 0))
        else:
            unmatched_ids.append(result.get("order_id", ""))

    if isinstance(refund_total, int) and refund_total > 0:
        net_total -= refund_total

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

