      "assertion": "assert match_payments([{'type': 'ORDER', 'order_id': 'o', 'timestamp': datetime(2024, 1, 1, 0, 0)}, {'type': 'PAYMENT', 'order_id': 'o', 'amount': 125, 'timestamp': datetime(2024, 1, 4, 0, 1)}]) == [{'order_id': 'o', 'status': 'unmatched', 'amount': 0}]",
      "result": "OBSERVED_PASS",
