"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    if s.startswith("-"):
        body = s[1:]
    else:
        body = s
    if not body or body.count(".") > 1:
        return None
    if "." in body:
        whole, fraction = body.split(".")
        if (whole and not whole.isdigit()) or (fraction and not fraction.isdigit()):
            return None
        if not whole and not fraction:
            return None
        if len(fraction) > 3:
            return None
    elif not body.isdigit():
        return None
    try:
        value = Decimal(s)
        cents = (value * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        )
        return int(cents)
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
    if record_type not in ("ORDER", "order", "PAYMENT", "payment"):
        return None
    record_id = record_id.strip()
    order_id = order_id.strip()
    currency = currency.strip()
    if not record_id or not order_id or currency != "USD":
        return None
    amount = parse_amount(amount_text)
    if amount is None:
        return None
    record_type = record_type.upper()
    if record_type == "ORDER" and (record_id != order_id or amount < 0):
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None
    if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue
        record_id = record["record_id"]
        if record_id in seen:
            continue
        seen.add(record_id)
        records.append(record)
    return records


def match_payments(records):
    results = []
    for order in records:
        if order["type"] != "ORDER":
            continue
        earliest = order["timestamp"]
        latest = earliest + timedelta(hours=72)
        chosen = None
        for payment in records:
            if payment["type"] != "PAYMENT":
                continue
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["amount"] < 0:
                continue
            payment_time = payment["timestamp"]
            if earliest <= payment_time <= latest:
                if chosen is None or payment_time < chosen["timestamp"]:
                    chosen = payment
        if chosen is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": chosen["amount"],
            })
    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += -record["amount"]
    return total


def build_summary(matches, refund_total):
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for match in matches:
        if match["status"] == "matched":
            matched_count += 1
            net_total += match["amount"]
        else:
            unmatched_ids.append(match["order_id"])

    unmatched_ids.sort()
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

