"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    try:
        if s.count('.') > 1 or any(c not in '0123456789.-' for c in s):
            return None
        if s.count('.') == 1:
            integer_part, fractional_part = s.split('.')
            if len(fractional_part) > 3:
                return None
            amount = Decimal(s).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        else:
            amount = Decimal(s)
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount, currency, timestamp = map(str.strip, fields)

    if record_type.upper() not in ['ORDER', 'PAYMENT']:
        return None
    if record_type.upper() == 'ORDER' and record_id != order_id:
        return None
    if currency != 'USD':
        return None
    parsed_amount = parse_amount(amount)
    if parsed_amount is None or (record_type.upper() == 'ORDER' and parsed_amount < 0):
        return None
    try:
        parsed_timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type.upper(),
        'record_id': record_id,
        'order_id': order_id,
        'amount': parsed_amount,
        'currency': currency,
        'timestamp': parsed_timestamp
    }


def load_records(text):
    records = {}
    result = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'].strip() not in records:
            records[record['record_id'].strip()] = record
            result.append(record)
    return result


def match_payments(records):
    orders = {}
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = record
        elif record['type'] == 'PAYMENT' and record['amount'] >= 0:
            payments.append(record)

    results = []

    for order_id, order in orders.items():
        matched_payment = None
        order_timestamp = order['timestamp']
        order_deadline = order_timestamp + timedelta(hours=72)

        for payment in payments:
            if (payment['order_id'] == order_id and 
                order_timestamp <= payment['timestamp'] <= order_deadline):
                if matched_payment is None or payment['timestamp'] < matched_payment['timestamp']:
                    matched_payment = payment

        if matched_payment:
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': matched_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    total_refund = 0
    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0:
            total_refund += abs(record['amount'])
    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'] == 'unmatched')

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a decimal monetary value to integer cents."""
    if not isinstance(s, str):
        return None

    value = s.strip()
    if not value:
        return None

    if value.startswith("-"):
        digits = value[1:]
    else:
        digits = value

    if digits.count(".") > 1 or "." in digits:
        whole, fraction = digits.split(".", 1)
        if not whole.isdigit() or not fraction.isdigit():
            return None
        if len(fraction) > 3:
            return None
    elif not digits.isdigit():
        return None

    try:
        amount = Decimal(value)
        if not amount.is_finite():
            return None
        cents = (amount * Decimal("100")).quantize(
            Decimal("1"),
            rounding=ROUND_HALF_UP,
        )
        return int(cents)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    """Parse one valid input record."""
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type = fields[0].upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None

    record_id = fields[1].strip()
    order_id = fields[2].strip()
    if not record_id or not order_id:
        return None

    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(fields[3])
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    if fields[4] != "USD":
        return None

    timestamp_text = fields[5]
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None
    if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": "USD",
        "timestamp": timestamp,
    }


def load_records(text):
    """Parse all valid records, retaining the first valid ID occurrence."""
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue
        if record["record_id"] in seen_ids:
            continue
        seen_ids.add(record["record_id"])
        records.append(record)

    return records


def match_payments(records):
    """Match each order with its earliest qualifying payment."""
    if not isinstance(records, list):
        return []

    orders = []
    payments = []

    for record in records:
        if not isinstance(record, dict):
            continue

        record_type = record.get("type")
        if record_type == "ORDER":
            orders.append(record)
        elif record_type == "PAYMENT":
            payments.append(record)

    results = []

    for order in orders:
        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        best_payment = None

        if isinstance(order_id, str) and isinstance(order_time, datetime):
            latest_time = order_time + timedelta(hours=72)

            for payment in payments:
                if payment.get("order_id") != order_id:
                    continue

                payment_amount = payment.get("amount")
                payment_time = payment.get("timestamp")

                if not isinstance(payment_amount, int):
                    continue
                if payment_amount < 0:
                    continue
                if not isinstance(payment_time, datetime):
                    continue
                if payment_time < order_time or payment_time > latest_time:
                    continue

                if (
                    best_payment is None
                    or payment_time < best_payment.get("timestamp")
                ):
                    best_payment = payment

        if best_payment is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": best_payment["amount"],
            })

    return results


def compute_refunds(records):
    """Compute the positive total of all negative payment amounts."""
    if not isinstance(records, list):
        return 0

    refund_total = 0

    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue

        amount = record.get("amount")
        if isinstance(amount, int) and not isinstance(amount, bool) and amount < 0:
            refund_total += abs(amount)

    return refund_total


def build_summary(matches, refund_total):
    """Build the settlement summary."""
    if not isinstance(matches, list):
        matches = []

    matched_count = 0
    matched_total = 0
    unmatched_ids = []

    for result in matches:
        if not isinstance(result, dict):
            continue

        if result.get("status") == "matched":
            matched_count += 1
            amount = result.get("payment_amount", result.get("amount", 0))
            if isinstance(amount, int) and not isinstance(amount, bool):
                matched_total += amount
        elif result.get("status") == "unmatched":
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.append(order_id)

    if (
        isinstance(refund_total, int)
        and not isinstance(refund_total, bool)
        and refund_total > 0
    ):
        matched_total -= refund_total

    unmatched_ids.sort()

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": matched_total,
        "unmatched_ids": unmatched_ids,
    }

