def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None

    text = s
    if text.startswith("-"):
        text = text[1:]

    if not text or text.count(".") > 1:
        return None

    parts = text.split(".")
    if not any(character in "0123456789" for character in text):
        return None

    for character in text:
        if character != "." and character not in "0123456789":
            return None

    fractional = parts[1] if len(parts) == 2 else ""
    if len(fractional) > 3:
        return None

    try:
        amount = Decimal(s) * Decimal("100")
        rounded = amount.quantize(Decimal("1"), rounding=ROUND_HALF_UP)
        return int(rounded)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields

    if record_type.upper() not in ("ORDER", "PAYMENT"):
        return None

    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    currency = currency.strip()

    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    if len(timestamp_text) != 16:
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    results = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        order_time = order["timestamp"]
        latest_time = order_time + timedelta(hours=72)
        chosen = None

        for payment in records:
            if payment["type"] != "PAYMENT":
                continue
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["amount"] < 0:
                continue
            if payment["timestamp"] < order_time:
                continue
            if payment["timestamp"] > latest_time:
                continue

            if chosen is None or payment["timestamp"] < chosen["timestamp"]:
                chosen = payment

        if chosen is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": chosen["amount"],
            })

    return results


def compute_refunds(records):
    total = 0

    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += -record["amount"]

    return total


def build_summary(matches, refund_total):
    matched_count = 0
