        negative = True
        text = s[1:]
    else:
        negative = False
        text = s

    if text.count(".") > 1:
        return None

    if "." in text:
        whole, fraction = text.split(".")
    else:
        whole, fraction = text, ""

    if not whole and not fraction:
        return None

    if any(character not in "0123456789" for character in whole):
        return None
    if any(character not in "0123456789" for character in fraction):
        return None
    if len(fraction) > 3:
        return None

    whole_value = int(whole) if whole else 0
    cents_text = (fraction + "00")[:2]
    cents_value = int(cents_text) if cents_text else 0

    if len(fraction) == 3 and fraction[2] >= "5":
        cents_value += 1

    total_cents = whole_value * 100 + cents_value
    return -total_cents if negative else total_cents


def parse_record(line):
    if not isinstance(line, str):
