    if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    """Match each order with the earliest qualifying payment."""
    if not isinstance(records, list):
        return []

    orders = []
    payments = []

    for position, record in enumerate(records):
        if not isinstance(record, dict):
            continue

        record_type = record.get("type")
        if record_type == "ORDER":
            orders.append(record)
        elif record_type == "PAYMENT":
            amount = record.get("amount")
            if isinstance(amount, int) and amount >= 0:
                payments.append((position, record))

    results = []

    for order in orders:
        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        chosen = None

        if order_time is not None:
            deadline = order_time + timedelta(hours=72)

            for position, payment in payments:
                if payment.get("order_id") != order_id:
                    continue

                payment_time = payment.get("timestamp")
                if payment_time is None:
                    continue

                if order_time <= payment_time <= deadline:
                    candidate = (payment_time, position, payment)
                    if chosen is None or candidate[:2] < chosen[:2]:
                        chosen = candidate

        if chosen is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": chosen[2]["amount"],
            })

    return results


def compute_refunds(records):
    """Return the total in cents of all negative payment amounts."""
    if not isinstance(records, list):
        return 0

    refund_total = 0

    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue

        amount = record.get("amount")
        if isinstance(amount, int) and not isinstance(amount, bool) and amount < 0:
            refund_total += abs(amount)

    return refund_total


def build_summary(matches, refund_total):
    """Build the summary report for matched and unmatched orders."""
    if not isinstance(matches, list):
        matches = []

    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for result in matches:
        if not isinstance(result, dict):
            continue

        if result.get("status") == "matched":
            matched_count += 1
            net_total += result.get("amount", result.get("payment_amount", 0))
        else:
            order_id = result.get("order_id")
            if order_id is not None:
                unmatched_ids.append(order_id)

    if isinstance(refund_total, int) and not isinstance(refund_total, bool):
        net_total -= max(0, refund_total)

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

