from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or s == "":
        return None

    negative = False
    if s.startswith("-"):
        negative = True
        s = s[1:]

    if s == "" or s.count(".") > 1:
        return None

    parts = s.split(".")
    whole = parts[0]
    fraction = parts[1] if len(parts) == 2 else ""

    if whole == "" and fraction == "":
        return None

    for character in whole + fraction:
        if character < "0" or character > "9":
            return None

    if len(fraction) > 3:
        return None

    try:
        whole_cents = int(whole or "0") * 100
        cents_text = (fraction + "00")[:2]
        cents = int(cents_text)

        if len(fraction) == 3 and fraction[2] >= "5":
            cents += 1

        result = whole_cents + cents
        if negative:
            result = -result
        return result
    except (TypeError, ValueError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    currency = currency.strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None

    if record_id == "" or order_id == "":
        return None

    if record_type == "ORDER" and record_id != order_id:
        return None

    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    if (
        len(timestamp_text) != 16
        or timestamp_text[4] != "-"
        or timestamp_text[7] != "-"
        or timestamp_text[10] != " "
        or timestamp_text[13] != ":"
    ):
        return None

    digit_positions = (
        list(range(0, 4))
        + list(range(5, 7))
        + list(range(8, 10))
        + list(range(11, 13))
        + list(range(14, 16))
    )
    if any(not timestamp_text[index].isdigit() for index in digit_positions):
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    seen_record_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_record_ids:
            continue

        seen_record_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    results = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        order_time = order["timestamp"]
        last_time = order_time + timedelta(hours=72)
        best_payment = None
        best_key = None

        for source_index, payment in enumerate(records):
            if payment["type"] != "PAYMENT":
                continue
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["amount"] < 0:
                continue

            payment_time = payment["timestamp"]
            if payment_time < order_time or payment_time > last_time:
                continue

            payment_key = (payment_time, source_index)
            if best_key is None or payment_key < best_key:
                best_key = payment_key
                best_payment = payment

        if best_payment is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": best_payment["amount"],
            })

    return results


def compute_refunds(records):
    total = 0

    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += -record["amount"]

    return total


def build_summary(matches, refund_total):
    matched_total = sum(
        result["amount"]
        for result in matches
        if result["status"] == "matched"
    )

    unmatched_ids = sorted(
        result["order_id"]
        for result in matches
        if result["status"] != "matched"
    )

    return {
        "total_orders": len(matches),
        "matched_count": sum(
            1 for result in matches if result["status"] == "matched"
        ),
        "net_total": matched_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

