from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Parse a monetary value and return its amount in cents.

    Invalid values return None instead of raising an exception.
    """
    if not isinstance(s, str):
        return None

    try:
        text = s.strip()
        if not text:
            return None

        if text.startswith("-"):
            number = text[1:]
        else:
            number = text

        if not number or number.count(".") > 1:
            return None

        if "." in number:
            whole, fraction = number.split(".")
            if not whole or not fraction or len(fraction) > 3:
                return None
        else:
            whole = number

        if not whole.isdigit():
            return None
        if "." in number and not fraction.isdigit():
            return None

        value = Decimal(text)
        if not value.is_finite():
            return None

        cents = value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        return int(cents * 100)
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    type_text, record_id, order_id, amount_text, currency, timestamp_text = fields
    record_type = type_text.upper()

    if record_type not in ("ORDER", "PAYMENT"):
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()

    if not record_id or not order_id:
        return None

    if record_type == "ORDER" and record_id != order_id:
        return None

    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None

    if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": "USD",
        "timestamp": timestamp,
    }


def load_records(text):
    records = []
    seen_record_ids = set()

    if not isinstance(text, str):
        return records

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_record_ids:
            continue

        seen_record_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    """Match each order with the earliest qualifying non-refund payment."""
    orders = []
    payments_by_order = {}

    for source_index, record in enumerate(records):
        if record.get("type") == "ORDER":
            orders.append(record)
        elif record.get("type") == "PAYMENT":
            if record.get("amount", 0) >= 0:
                order_id = record.get("order_id")
                payments_by_order.setdefault(order_id, []).append(
                    (record.get("timestamp"), source_index, record)
                )

    matches = []

    for order in orders:
        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        latest_time = order_time + timedelta(hours=72)

        qualifying = []
        for payment_time, source_index, payment in payments_by_order.get(
            order_id, []
        ):
            if order_time <= payment_time <= latest_time:
                qualifying.append((payment_time, source_index, payment))

        if qualifying:
            _, _, payment = min(qualifying, key=lambda item: (item[0], item[1]))
            matches.append({
                "order_id": order_id,
                "status": "matched",
                "amount": payment["amount"],
            })
        else:
            matches.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })

    return matches


def compute_refunds(records):
    total = 0
    for record in records:
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and record["amount"] < 0
        ):
            total += abs(record["amount"])
    return total


def build_summary(matches, refund_total):
    """Build the reconciliation summary."""
    total_orders = len(matches)
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for result in matches:
        status = result.get("status")

        if status == "matched":
            matched_count += 1
            net_total += result.get("amount", 0)
        else:
            order_id = result.get("order_id")
            if order_id is not None:
                unmatched_ids.append(order_id)

    net_total -= refund_total

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

