from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None

    try:
        # Check for valid format
        if s.count('.') > 1 or any(c not in '0123456789.-' for c in s):
            return None

        # Convert to Decimal
        amount = Decimal(s)

        # Check for more than 2 decimal places
        if amount.as_tuple().exponent < -2:
            return None

        # Round using round-half-up
        amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

        # Return as integer cents
        return int(amount * 100)

    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')

    if len(fields) != 6:
        return None

    record_type = fields[0].strip().upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    amount_str = fields[3].strip()
    currency = fields[4].strip()
    timestamp_str = fields[5].strip()

    if record_type not in {'ORDER', 'PAYMENT'}:
        return None

    if not record_id or not order_id:
        return None

    if record_type == 'ORDER' and record_id != order_id:
        return None

    if currency != 'USD':
        return None

    amount = parse_amount(amount_str)
    if amount is None:
        return None

    if record_type == 'ORDER' and amount < 0:
        return None

    if record_type == 'PAYMENT' and amount > 0:
        return None

    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['record_id'])

    return records


def match_payments(records):
    results = []

    for record in records:
        if record['type'] == 'ORDER':
            order_id = record['order_id']
            order_timestamp = record['timestamp']
            end_timestamp = order_timestamp + timedelta(hours=72)

            # Filter for matching payments
            qualifying_payments = [
                payment for payment in records
                if payment['type'] == 'PAYMENT' and
                payment['order_id'] == order_id and
                payment['amount'] >= 0 and
                order_timestamp <= payment['timestamp'] <= end_timestamp
            ]

            if qualifying_payments:
                # Sort by timestamp and then by original order
                qualifying_payments.sort(key=lambda x: (x['timestamp'], records.index(x)))
                earliest_payment = qualifying_payments[0]
                results.append({
                    'order_id': order_id,
                    'status': 'matched',
                    'amount': earliest_payment['amount']
                })
            else:
                results.append({
                    'order_id': order_id,
                    'status': 'unmatched',
                    'amount': 0
                })

    return results


def compute_refunds(records):
    refund_total = 0

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0:
            refund_total += abs(record['amount'])

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'] == 'unmatched')

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

