from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a decimal monetary value to integer cents."""
    if not isinstance(s, str):
        return None

    text = s.strip()
    if text.startswith("-"):
        digits = text[1:]
    else:
        digits = text

    if not digits:
        return None

    if "." in digits:
        if digits.count(".") != 1:
            return None
        whole, fraction = digits.split(".")
        if not whole or not fraction or len(fraction) > 3:
            return None
    else:
        whole, fraction = digits, ""

    if not whole.isdigit() or (fraction and not fraction.isdigit()):
        return None

    try:
        value = Decimal(text)
        cents = value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        return int(cents * 100)
    except (InvalidOperation, TypeError, ValueError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None

    parts = line.split("|")
    if len(parts) != 6:
        return None

    record_type = parts[0].upper()
    record_id = parts[1].strip()
    order_id = parts[2].strip()
    currency = parts[4]

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    if currency != "USD":
        return None

    amount = parse_amount(parts[3])
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    timestamp_text = parts[5]
    if len(timestamp_text) != 16:
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    records = []
    seen_ids = set()

    if not isinstance(text, str):
        return records

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue
        if record["record_id"] in seen_ids:
            continue
        seen_ids.add(record["record_id"])
        records.append(record)

    return records


def match_payments(records):
    """Match each order with its earliest qualifying payment."""
    orders = []
    payments = []

    for record in records:
        if record.get("type") == "ORDER":
            orders.append(record)
        elif record.get("type") == "PAYMENT" and record.get("amount", 0) >= 0:
            payments.append(record)

    results = []

    for order in orders:
        order_id = order["order_id"]
        start = order["timestamp"]
        end = start + timedelta(hours=72)

        candidates = []
        for source_index, payment in enumerate(payments):
            if payment.get("order_id") != order_id:
                continue

            payment_time = payment["timestamp"]
            if start <= payment_time <= end:
                candidates.append((payment_time, source_index, payment))

        if candidates:
            candidates.sort(key=lambda item: (item[0], item[1]))
            payment = candidates[0][2]
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": payment["amount"],
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })

    return results


def compute_refunds(records):
    """Return the total cents represented by negative payments."""
    refund_total = 0

    for record in records:
        if record.get("type") == "PAYMENT":
            amount = record.get("amount")
            if amount < 0:
                refund_total += abs(amount)

    return refund_total


def build_summary(matches, refund_total):
    """Build a summary of order-payment matching results."""
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for result in matches:
        if result.get("status") == "matched":
            matched_count += 1
            net_total += result.get("amount", 0)
        else:
            unmatched_ids.append(result.get("order_id"))

    net_total -= refund_total
    unmatched_ids.sort()

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids,
    }

