"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    try:
        if s.count('.') > 1 or any(c not in '0123456789.-' for c in s):
            return None
        if s.count('.') == 1:
            whole, frac = s.split('.')
            if len(frac) > 3:
                return None
            frac = frac.ljust(3, '0')[:3]  # Pad or truncate to 3 digits
            s = f"{whole}.{frac}"
        amount = Decimal(s)
        return int(amount.scaleb(2).to_integral_value(rounding=ROUND_HALF_UP))
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.strip().upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    currency = currency.strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id:
        return None
    if record_type == 'ORDER' and record_id != order_id:
        return None
    if currency != 'USD':
        return None
    amount = parse_amount(amount)
    if amount is None or (record_type == 'ORDER' and amount < 0):
        return None
    try:
        timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'].strip() not in seen_ids:
            records.append(record)
            seen_ids.add(record['record_id'].strip())
    return records


def match_payments(records):
    results = []
    orders = [record for record in records if record['type'] == 'ORDER']

    for order in orders:
        order_id = order['order_id']
        order_timestamp = order['timestamp']
        qualifying_payments = [
            record for record in records
            if record['type'] == 'PAYMENT' and
            record['order_id'] == order_id and
            record['amount'] >= 0 and
            order_timestamp <= record['timestamp'] <= order_timestamp + timedelta(hours=72)
        ]

        if qualifying_payments:
            earliest_payment = min(qualifying_payments, key=lambda x: (x['timestamp'], records.index(x)))
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': earliest_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    total_refund = 0
    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0:
            total_refund += abs(record['amount'])
    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'] == 'unmatched')

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

