from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None

    negative = False
    if s.startswith("-"):
        negative = True
        s = s[1:]

    if not s or s.count(".") > 1:
        return None

    if "." in s:
        whole, fraction = s.split(".")
    else:
        whole, fraction = s, ""

    if not whole and not fraction:
        return None

    if (whole and not all("0" <= char <= "9" for char in whole)) or (
        fraction and not all("0" <= char <= "9" for char in fraction)
    ):
        return None

    if len(fraction) > 3:
        return None

    whole = whole or "0"
    cents = int(whole) * 100
    fraction = (fraction + "00")[:3]
    cents += int(fraction[:2])

    if fraction[2] >= "5":
        cents += 1

    return -cents if negative else cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp = fields

    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id:
        return None

    if record_type == "ORDER" and record_id != order_id:
        return None

    currency = currency.strip()
    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    try:
        parsed_timestamp = datetime.strptime(timestamp, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None

    if timestamp != parsed_timestamp.strftime("%Y-%m-%d %H:%M"):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": parsed_timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    seen_record_ids = set()

    for line in text.splitlines():
        try:
            record = parse_record(line)
        except Exception:
            record = None

        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_record_ids:
            continue

        seen_record_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    results = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        earliest_payment = None
        deadline = order["timestamp"] + timedelta(hours=72)

        for payment in records:
            if payment["type"] != "PAYMENT":
                continue
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["amount"] < 0:
                continue
            if payment["timestamp"] < order["timestamp"]:
                continue
            if payment["timestamp"] > deadline:
                continue

            if (
                earliest_payment is None
                or payment["timestamp"] < earliest_payment["timestamp"]
            ):
                earliest_payment = payment

        if earliest_payment is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": earliest_payment["amount"],
            })

    return results


def compute_refunds(records):
    total = 0

    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += -record["amount"]

    return total


def build_summary(matches, refund_total):
    matched_total = 0
    unmatched_ids = []

    for result in matches:
        if result["status"] == "matched":
            matched_total += result["amount"]
        else:
            unmatched_ids.append(result["order_id"])

    unmatched_ids.sort()

    return {
        "total_orders": len(matches),
        "matched_count": sum(
            1 for result in matches if result["status"] == "matched"
        ),
        "net_total": matched_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

