from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None

    try:
        if s == "":
            return None

        negative = s.startswith("-")
        text = s[1:] if negative else s

        if text == "":
            return None

        if text.count(".") > 1:
            return None

        if "." in text:
            whole, fraction = text.split(".")
        else:
            whole, fraction = text, ""

        if whole == "" and fraction == "":
            return None

        for character in whole + fraction:
            if character < "0" or character > "9":
                return None

        if len(fraction) > 3:
            return None

        cents = 0
        for character in whole:
            cents = cents * 10 + (ord(character) - ord("0"))

        cents *= 100

        if len(fraction) >= 1:
            cents += (ord(fraction[0]) - ord("0")) * 10
        if len(fraction) >= 2:
            cents += ord(fraction[1]) - ord("0")
        if len(fraction) == 3 and fraction[2] >= "5":
            cents += 1

        return -cents if negative else cents
    except Exception:
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields

    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()
    if record_id == "" or order_id == "":
        return None

    if record_type == "ORDER" and record_id != order_id:
        return None

    currency = currency.strip()
    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    if (
        len(timestamp_text) != 16
        or timestamp_text[4] != "-"
        or timestamp_text[7] != "-"
        or timestamp_text[10] != " "
        or timestamp_text[13] != ":"
    ):
        return None

    for index, character in enumerate(timestamp_text):
        if index not in (4, 7, 10, 13):
            if character < "0" or character > "9":
                return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (ValueError, TypeError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    seen_record_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"].strip()
        if record_id in seen_record_ids:
            continue

        seen_record_ids.add(record_id)
        records.append({
            "type": record["type"],
            "record_id": record_id,
            "order_id": record["order_id"],
            "amount": record["amount"],
            "currency": record["currency"],
            "timestamp": record["timestamp"],
        })

    return records


def match_payments(records):
    results = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        order_time = order["timestamp"]
        latest_time = order_time + timedelta(hours=72)
        best_payment = None

        for payment in records:
            if payment["type"] != "PAYMENT":
                continue
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["amount"] < 0:
                continue
            if payment["timestamp"] < order_time:
                continue
            if payment["timestamp"] > latest_time:
                continue

            if (
                best_payment is None
                or payment["timestamp"] < best_payment["timestamp"]
            ):
                best_payment = payment

        if best_payment is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": best_payment["amount"],
            })

    return results


def compute_refunds(records):
    total = 0

    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += -record["amount"]

    return total


def build_summary(matches, refund_total):
    matched_total = sum(
        result["amount"]
        for result in matches
        if result["status"] == "matched"
    )

    unmatched_ids = sorted(
        result["order_id"]
        for result in matches
        if result["status"] == "unmatched"
    )

    return {
        "total_orders": len(matches),
        "matched_count": sum(
            1 for result in matches if result["status"] == "matched"
        ),
        "net_total": matched_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

