from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None

    if s == "":
        return None

    negative = s.startswith("-")
    if negative:
        s = s[1:]

    if s == "":
        return None

    if any(character not in "0123456789." for character in s):
        return None

    if s.count(".") > 1:
        return None

    if not any(character.isdigit() for character in s):
        return None

    if "." in s:
        whole_text, fraction_text = s.split(".")
    else:
        whole_text, fraction_text = s, ""

    if len(fraction_text) > 3:
        return None

    if whole_text == "":
        whole_text = "0"

    try:
        whole = int(whole_text)
        fraction = fraction_text.ljust(3, "0")
        cents = int(fraction[:2]) if fraction else 0

        if len(fraction) == 3 and int(fraction[2]) >= 5:
            cents += 1

        amount = whole * 100 + cents
    except (TypeError, ValueError, OverflowError):
        return None

    return -amount if negative else amount


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp = fields

    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()
    if record_id == "" or order_id == "":
        return None

    if record_type == "ORDER" and record_id != order_id:
        return None

    currency = currency.strip()
    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    if (
        len(timestamp) != 16
        or timestamp[4] != "-"
        or timestamp[7] != "-"
        or timestamp[10] != " "
        or timestamp[13] != ":"
        or not timestamp[:4].isdigit()
        or not timestamp[5:7].isdigit()
        or not timestamp[8:10].isdigit()
        or not timestamp[11:13].isdigit()
        or not timestamp[14:16].isdigit()
    ):
        return None

    try:
        parsed_timestamp = datetime.strptime(timestamp, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": parsed_timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    seen_record_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"].strip()
        if record_id in seen_record_ids:
            continue

        seen_record_ids.add(record_id)
        records.append({
            "type": record["type"],
            "record_id": record_id,
            "order_id": record["order_id"],
            "amount": record["amount"],
            "currency": record["currency"],
            "timestamp": record["timestamp"],
        })

    return records


def match_payments(records):
    results = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        order_timestamp = order["timestamp"]
        latest_timestamp = order_timestamp + timedelta(hours=72)
        best_payment = None

        for payment in records:
            if payment["type"] != "PAYMENT":
                continue
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["amount"] < 0:
                continue

            payment_timestamp = payment["timestamp"]
            if (
                order_timestamp <= payment_timestamp
                and payment_timestamp <= latest_timestamp
            ):
                if (
                    best_payment is None
                    or payment_timestamp < best_payment["timestamp"]
                ):
                    best_payment = payment

        if best_payment is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": best_payment["amount"],
            })

    return results


def compute_refunds(records):
    total = 0

    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += -record["amount"]

    return total


def build_summary(matches, refund_total):
    matched_amount = 0
    unmatched_ids = []
    matched_count = 0

    for result in matches:
        if result["status"] == "matched":
            matched_count += 1
            matched_amount += result["amount"]
        else:
            unmatched_ids.append(result["order_id"])

    unmatched_ids.sort()

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": matched_amount - refund_total,
        "unmatched_ids": unmatched_ids,
    }

