"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None
    start = 1 if s[0] == "-" else 0
    if start == len(s):
        return None
    digits_before = 0
    digits_after = 0
    seen_dot = False
    for char in s[start:]:
        if char == ".":
            if seen_dot:
                return None
            seen_dot = True
        elif "0" <= char <= "9":
            if seen_dot:
                digits_after += 1
            else:
                digits_before += 1
        else:
            return None
    if digits_before == 0 or digits_after > 3:
        return None
    try:
        amount = Decimal(s)
        cents = amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        return int(cents * 100)
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()
    currency = currency.strip()
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None

    if len(timestamp_text) != 16:
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None
    if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen_ids = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue
        record_id = record["record_id"]
        if record_id in seen_ids:
            continue
        seen_ids.add(record_id)
        records.append(record)
    return records


def match_payments(records):
    results = []
    for order in records:
        if order["type"] != "ORDER":
            continue

        earliest = None
        deadline = order["timestamp"] + timedelta(hours=72)

        for payment in records:
            if payment["type"] != "PAYMENT":
                continue
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["amount"] < 0:
                continue
            if payment["timestamp"] < order["timestamp"]:
                continue
            if payment["timestamp"] > deadline:
                continue
            if earliest is None or payment["timestamp"] < earliest["timestamp"]:
                earliest = payment

        if earliest is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": earliest["amount"],
            })
    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += -record["amount"]
    return total


def build_summary(matches, refund_total):
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for match in matches:
        if match["status"] == "matched":
            matched_count += 1
            net_total += match["amount"]
        else:
            unmatched_ids.append(match["order_id"])

    unmatched_ids.sort()
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Convert the string amount to a Decimal, then to an integer in cents
        amount = Decimal(s.strip())
        return int(amount * 100)  # Convert dollars to cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_str, currency, timestamp_str = map(str.strip, fields)

    # Normalize type to uppercase
    record_type = record_type.upper()

    # Validate type
    if record_type not in {"ORDER", "PAYMENT"}:
        return None

    # Validate record_id and order_id
    if not record_id or not order_id or record_id != order_id:
        return None

    # Parse amount
    amount = parse_amount(amount_str)
    if amount is None:
        return None

    # Validate currency
    if currency != "USD":
        return None

    # Validate timestamp
    try:
        timestamp = datetime.strptime(timestamp_str, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record["record_id"] not in {r["record_id"] for r in records}:
            records.append(record)
    return records


def match_payments(records):
    orders = {}
    payments = {}

    # Separate orders and payments
    for record in records:
        if record["type"] == "ORDER":
            orders[record["order_id"]] = record
        elif record["type"] == "PAYMENT":
            payments.setdefault(record["order_id"], []).append(record)

    results = []

    for order_id, order in orders.items():
        order_timestamp = order["timestamp"]
        order_amount = order["amount"]
        matched_payment = None

        # Check for matching payments
        if order_id in payments:
            for payment in payments[order_id]:
                if payment["amount"] >= 0:  # Only consider non-refund payments
                    payment_timestamp = payment["timestamp"]
                    if order_timestamp <= payment_timestamp <= order_timestamp + timedelta(hours=72):
                        if matched_payment is None or payment_timestamp < matched_payment["timestamp"]:
                            matched_payment = payment

        if matched_payment:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": matched_payment["amount"],
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })

    return results


def compute_refunds(records):
    refund_total = 0

    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            refund_total += -record["amount"]  # Subtracting negative amounts to get positive total

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched')
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'] != 'matched')

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids,
    }

