"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a decimal monetary value to an integer number of cents."""
    if not isinstance(s, str):
        return None

    value = s.strip()
    if not re.fullmatch(r"-?\d+(?:\.\d{0,3})?", value):
        return None

    try:
        amount = Decimal(value)
        cents = (amount * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        )
        return int(cents)
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    if not re.fullmatch(r"\d{4}-\d{2}-\d{2} \d{2}:\d{2}", timestamp_text):
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": "USD",
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue
        if record["record_id"] in seen_ids:
            continue
        seen_ids.add(record["record_id"])
        records.append(record)

    return records


def match_payments(records):
    results = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        earliest_time = order["timestamp"]
        latest_time = earliest_time + timedelta(hours=72)
        selected_payment = None

        for payment in records:
            if payment["type"] != "PAYMENT":
                continue
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["amount"] < 0:
                continue
            if payment["timestamp"] < earliest_time:
                continue
            if payment["timestamp"] > latest_time:
                continue

            if (
                selected_payment is None
                or payment["timestamp"] < selected_payment["timestamp"]
            ):
                selected_payment = payment

        if selected_payment is None:
            results.append(
                {
                    "order_id": order["order_id"],
                    "status": "unmatched",
                    "amount": 0,
                }
            )
        else:
            results.append(
                {
                    "order_id": order["order_id"],
                    "status": "matched",
                    "amount": selected_payment["amount"],
                }
            )

    return results


def compute_refunds(records):
    refund_total = 0

    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            refund_total += abs(record["amount"])

    return refund_total


def build_summary(matches, refund_total):
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for result in matches:
        if result["status"] == "matched":
            matched_count += 1
            net_total += result["amount"]
        else:
            unmatched_ids.append(result["order_id"])

    net_total -= refund_total
    unmatched_ids.sort()

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids,
    }

"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a valid decimal monetary value to integer cents."""
    if not isinstance(s, str) or not s:
        return None

    value = s
    if value.startswith("-"):
        value = value[1:]

    if not value or value.count(".") > 1:
        return None

    if "." in value:
        whole, fraction = value.split(".")
        if not whole or not whole.isdigit():
            return None
        if fraction and not fraction.isdigit():
            return None
        if len(fraction) > 3:
            return None
    elif not value.isdigit():
        return None

    try:
        amount = Decimal(s)
        if not amount.is_finite():
            return None
        cents = amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        return int(cents * 100)
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type = fields[0].upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    amount_text = fields[3]
    currency = fields[4]
    timestamp_text = fields[5]

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    if (
        len(timestamp_text) != 16
        or timestamp_text[4] != "-"
        or timestamp_text[7] != "-"
        or timestamp_text[10] != " "
        or timestamp_text[13] != ":"
        or not timestamp_text[:4].isdigit()
        or not timestamp_text[5:7].isdigit()
        or not timestamp_text[8:10].isdigit()
        or not timestamp_text[11:13].isdigit()
        or not timestamp_text[14:16].isdigit()
    ):
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue
        if record["record_id"] in seen_ids:
            continue
        seen_ids.add(record["record_id"])
        records.append(record)

    return records


def match_payments(records):
    payments = []

    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] >= 0:
            payments.append(record)

    results = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        earliest_payment = None
        latest_time = order["timestamp"] + timedelta(hours=72)

        for payment in payments:
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["timestamp"] < order["timestamp"]:
                continue
            if payment["timestamp"] > latest_time:
                continue

            if (
                earliest_payment is None
                or payment["timestamp"] < earliest_payment["timestamp"]
            ):
                earliest_payment = payment

        if earliest_payment is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": earliest_payment["amount"],
            })

    return results


def compute_refunds(records):
    total = 0

    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += -record["amount"]

    return total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for result in matches:
        if result["status"] == "matched":
            matched_count += 1
            net_total += result["amount"]
        else:
            unmatched_ids.append(result["order_id"])

    net_total -= refund_total
    unmatched_ids.sort()

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids,
    }

