from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    text = s.strip()
    if not text:
        return None
    if text.startswith("-"):
        body = text[1:]
    else:
        body = text
    if not body or body.count(".") > 1:
        return None
    parts = body.split(".")
    if not parts[0].isdigit():
        return None
    if len(parts) == 2 and parts[1] and not parts[1].isdigit():
        return None
    if len(parts) == 2 and len(parts[1]) > 3:
        return None
    try:
        value = Decimal(text)
        cents = (value * Decimal("100")).to_integral_value(
            rounding=ROUND_HALF_UP
        )
        return int(cents)
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
    record_type = fields[0].strip().upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    currency = fields[4].strip()
    if currency != "USD":
        return None
    amount = parse_amount(fields[3].strip())
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None
    timestamp_text = fields[5].strip()
    try:
        if len(timestamp_text) != 16:
            return None
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            records.append(record)
    return records


def match_payments(records):
    payments = []
    for source_index, record in enumerate(records):
        if record["type"] == "PAYMENT" and record["amount"] >= 0:
            payments.append((source_index, record))

    results = []
    for order in records:
        if order["type"] != "ORDER":
            continue
        earliest = order["timestamp"]
        latest = earliest + timedelta(hours=72)
        chosen = None
        chosen_index = None
        for source_index, payment in payments:
            if payment["order_id"] != order["order_id"]:
                continue
            timestamp = payment["timestamp"]
            if earliest <= timestamp <= latest:
                if chosen is None or timestamp < chosen["timestamp"]:
                    chosen = payment
                    chosen_index = source_index
                elif timestamp == chosen["timestamp"] and source_index < chosen_index:
                    chosen = payment
                    chosen_index = source_index
        if chosen is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": chosen["amount"],
            })
    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += -record["amount"]
    return total


def build_summary(matches, refund_total):
    unmatched = []
    matched_count = 0
    net_total = 0
    for result in matches:
        if result["status"] == "matched":
            matched_count += 1
            net_total += result["amount"]
        else:
            unmatched.append(result["order_id"])
    unmatched.sort()
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": unmatched,
    }

