from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    try:
        # Check for valid characters and format
        if s.count('.') > 1 or any(c not in '0123456789.-' for c in s):
            return None

        # Convert to Decimal
        amount = Decimal(s)

        # Check for more than 3 fractional digits
        if amount.as_tuple().exponent < -2:
            return None

        # Round using round-half-up
        rounded_amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

        # Return as integer cents
        return int(rounded_amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')

    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_str, currency, timestamp_str = map(str.strip, fields)

    # Validate TYPE
    record_type = record_type.upper()
    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    # Validate RECORD_ID and ORDER_ID
    if not record_id or not order_id or (record_type == 'ORDER' and record_id != order_id):
        return None

    # Validate CURRENCY
    currency = currency.strip()
    if currency != 'USD':
        return None

    # Parse AMOUNT
    amount = parse_amount(amount_str)
    if amount is None or (record_type == 'ORDER' and amount < 0):
        return None

    # Validate TIMESTAMP
    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    # Construct and return the record dictionary
    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['record_id'])

    return records


def match_payments(records):
    results = []

    for record in records:
        if record['type'] == 'ORDER':
            order_id = record['order_id']
            order_timestamp = record['timestamp']
            order_amount = record['amount']

            # Define the time window for matching payments
            start_time = order_timestamp
            end_time = order_timestamp + timedelta(hours=72)

            # Find qualifying payments
            qualifying_payments = [
                payment for payment in records
                if payment['type'] == 'PAYMENT' and
                payment['order_id'] == order_id and
                payment['amount'] >= 0 and
                start_time <= payment['timestamp'] <= end_time
            ]

            if qualifying_payments:
                # Sort by timestamp and then by original order
                qualifying_payments.sort(key=lambda x: (x['timestamp'], records.index(x)))
                earliest_payment = qualifying_payments[0]
                results.append({
                    'order_id': order_id,
                    'status': 'matched',
                    'amount': earliest_payment['amount']
                })
            else:
                results.append({
                    'order_id': order_id,
                    'status': 'unmatched',
                    'amount': 0
                })

    return results


