"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    try:
        if s.count('.') > 1 or any(c not in '0123456789.-' for c in s):
            return None
        if s.count('.') == 1:
            whole, frac = s.split('.')
            if len(frac) > 3:
                return None
            amount = Decimal(s).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        else:
            amount = Decimal(s)
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount, currency, timestamp = map(str.strip, fields)
    record_type = record_type.upper()
    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id or (record_type == 'ORDER' and record_id != order_id):
        return None
    if currency != 'USD':
        return None
    amount_parsed = parse_amount(amount)
    if amount_parsed is None or (record_type == 'ORDER' and amount_parsed < 0):
        return None
    try:
        timestamp_parsed = datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None
    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount_parsed,
        'currency': currency,
        'timestamp': timestamp_parsed
    }


def load_records(text):
    records = []
    seen_ids = set()
    for line in text.strip().split('\n'):
        record = parse_record(line)
        if record and record['record_id'].strip() not in seen_ids:
            records.append(record)
            seen_ids.add(record['record_id'].strip())
    return records


def match_payments(records):
    results = []
    orders = {record['order_id']: record for record in records if record['type'] == 'ORDER'}
    payments = [record for record in records if record['type'] == 'PAYMENT' and record['amount'] >= 0]

    for order_id, order in orders.items():
        matched_payment = None
        order_timestamp = order['timestamp']
        order_amount = order['amount']
        for payment in payments:
            if (payment['order_id'] == order_id and
                order_timestamp <= payment['timestamp'] <= order_timestamp + timedelta(hours=72)):
                if matched_payment is None or payment['timestamp'] < matched_payment['timestamp']:
                    matched_payment = payment

        if matched_payment:
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': matched_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    total_refund = 0
    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0:
            total_refund += abs(record['amount'])
    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'] == 'unmatched')

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

