        return int(amount * 100)  # Convert to cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    parts = line.split('|')
    if len(parts) != 6:
        return None
    record_type, record_id, order_id, amount, currency, timestamp = parts
    record_type = record_type.strip().upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    if record_type not in ['ORDER', 'PAYMENT'] or not record_id or not order_id:
        return None
    if record_type == 'ORDER' and record_id != order_id:
        return None
    if currency.strip() != 'USD':
        return None
    amount_cents = parse_amount(amount)
    if amount_cents is None:
        return None
    try:
        timestamp = datetime.strptime(timestamp.strip(), '%Y-%m-%d %H:%M')
    except ValueError:
        return None
    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount_cents,
        'currency': currency.strip(),
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    orders = {}
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = record
        elif record['type'] == 'PAYMENT':
            payments.append(record)

    results = []

    for order_id, order in orders.items():
        matched_payment = None
        order_timestamp = order['timestamp']

        for payment in payments:
            if (payment['amount'] >= 0 and 
                order_timestamp <= payment['timestamp'] <= order_timestamp + timedelta(hours=72) and
                (matched_payment is None or payment['timestamp'] < matched_payment['timestamp'])):
                matched_payment = payment

        if matched_payment:
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': matched_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    return sum(-record['amount'] for record in records if record['type'] == 'PAYMENT' and record['amount'] < 0)


def build_summary(matches, refund_total):
    return {
        'total_orders': len(matches),
        'matched_count': sum(1 for match in matches if match['status'] == 'matched'),
        'net_total': sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total,
        'unmatched_ids': sorted(set(match['order_id'] for match in matches if match['status'] != 'matched'))
    }

"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a decimal monetary value to an integer number of cents."""
    if not isinstance(s, str):
        return None

    value = s.strip()
    if not value:
        return None

    if value.startswith("-"):
        digits = value[1:]
    else:
        digits = value

    if not digits:
        return None

    if digits.count(".") > 1:
        return None

    if "." in digits:
        whole, fraction = digits.split(".")
        if not whole or not fraction:
            return None
        if len(fraction) > 3:
            return None
    else:
        whole = digits
        fraction = ""

    if not whole.isdigit() or (fraction and not fraction.isdigit()):
        return None

    try:
        amount = Decimal(value)
        if not amount.is_finite():
            return None
        cents = amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        return int(cents * 100)
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    """Parse one input line into a record dictionary."""
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields

    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None

    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    if currency != "USD":
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None

    if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": "USD",
        "timestamp": timestamp,
    }


def load_records(text):
    """Parse all valid records from a text export."""
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    """Return the earliest qualifying payment for each order."""
    results = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        order_time = order["timestamp"]
        latest_time = order_time + timedelta(hours=72)
        best_payment = None

        for payment in records:
            if payment["type"] != "PAYMENT":
                continue
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["amount"] < 0:
                continue
            if payment["timestamp"] < order_time:
                continue
            if payment["timestamp"] > latest_time:
                continue

            if best_payment is None:
                best_payment = payment

        if best_payment is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": best_payment["amount"],
            })

    return results


def compute_refunds(records):
    """Compute the total refund amount in cents."""
    total = 0

    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += abs(record["amount"])

    return total


def build_summary(matches, refund_total):
    """Build the settlement summary."""
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for result in matches:
        if result["status"] == "matched":
            matched_count += 1
            net_total += result["amount"]
        elif result["status"] == "unmatched":
            unmatched_ids.append(result["order_id"])

    unmatched_ids.sort()

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

