"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None

    text = s
    if text.startswith("-"):
        text = text[1:]

    if not text or text.count(".") > 1:
        return None

    if "." in text:
        whole, fraction = text.split(".")
    else:
        whole, fraction = text, ""

    if not whole and not fraction:
        return None
    if any(ch < "0" or ch > "9" for ch in whole + fraction):
        return None
    if len(fraction) > 3:
        return None

    try:
        value = Decimal(s)
        rounded = value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        return int(rounded * 100)
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    currency = currency.strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    if len(timestamp_text) != 16:
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None
    if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    records = []
    seen_ids = set()

    if not isinstance(text, str):
        return records

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue
        record_id = record["record_id"]
        if record_id in seen_ids:
            continue
        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    results = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        earliest = None
        deadline = order["timestamp"] + timedelta(hours=72)

        for payment in records:
            if payment["type"] != "PAYMENT":
                continue
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["amount"] < 0:
                continue
            if payment["timestamp"] < order["timestamp"]:
                continue
            if payment["timestamp"] > deadline:
                continue
            if earliest is None or payment["timestamp"] < earliest["timestamp"]:
                earliest = payment

        if earliest is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": earliest["amount"],
            })

    return results


def compute_refunds(records):
    total = 0

    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += -record["amount"]

    return total


def build_summary(matches, refund_total):
    matched_count = 0
    matched_total = 0
    unmatched_ids = []

    for match in matches:
        if match["status"] == "matched":
            matched_count += 1
            matched_total += match["amount"]
        else:
            unmatched_ids.append(match["order_id"])

    unmatched_ids.sort()

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": matched_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

