from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None

    if s.startswith("-"):
        negative = True
        text = s[1:]
    else:
        negative = False
        text = s

    if text.count(".") > 1:
        return None

    if "." in text:
        whole_part, fractional_part = text.split(".")
    else:
        whole_part = text
        fractional_part = ""

    if not whole_part and not fractional_part:
        return None

    if any(char < "0" or char > "9"
           for char in whole_part + fractional_part):
        return None

    if len(fractional_part) > 3:
        return None

    try:
        whole = int(whole_part or "0")
        cents = int((fractional_part + "00")[:2])

        if len(fractional_part) == 3 and fractional_part[2] >= "5":
            cents += 1

        result = whole * 100 + cents
        return -result if negative else result
    except (ValueError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields

    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id:
        return None

    if record_type == "ORDER" and record_id != order_id:
        return None

    if currency.strip() != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    if (
        len(timestamp_text) != 16
        or timestamp_text[4] != "-"
        or timestamp_text[7] != "-"
        or timestamp_text[10] != " "
        or timestamp_text[13] != ":"
        or any(
            not timestamp_text[index].isdigit()
            for index in (
                0, 1, 2, 3, 5, 6, 8, 9, 11, 12, 14, 15
            )
        )
    ):
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": "USD",
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    seen_record_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_record_ids:
            continue

        seen_record_ids.add(record_id)
        records.append({
            "type": record["type"],
            "record_id": record["record_id"],
            "order_id": record["order_id"],
            "amount": record["amount"],
            "currency": record["currency"],
            "timestamp": record["timestamp"],
        })

    return records


def match_payments(records):
    results = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        earliest_time = order["timestamp"]
        latest_time = earliest_time + timedelta(hours=72)
        chosen_payment = None

        for payment in records:
            if payment["type"] != "PAYMENT":
                continue
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["amount"] < 0:
                continue
            if payment["timestamp"] < earliest_time:
                continue
            if payment["timestamp"] > latest_time:
                continue

            if (
                chosen_payment is None
                or payment["timestamp"] < chosen_payment["timestamp"]
            ):
                chosen_payment = payment

        if chosen_payment is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": chosen_payment["amount"],
            })

    return results


def compute_refunds(records):
    total = 0

    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += abs(record["amount"])

    return total


def build_summary(matches, refund_total):
    matched_amount = sum(
        result["amount"]
        for result in matches
        if result["status"] == "matched"
    )

    unmatched_ids = sorted(
        result["order_id"]
        for result in matches
        if result["status"] != "matched"
    )

    return {
        "total_orders": len(matches),
        "matched_count": sum(
            1 for result in matches
            if result["status"] == "matched"
        ),
        "net_total": matched_amount - refund_total,
        "unmatched_ids": unmatched_ids,
    }

