"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        if not isinstance(s, str):
            return None
        text = s.strip()
        if not text:
            return None
        body = text[1:] if text.startswith("-") else text
        if not body or body.count(".") > 1:
            return None
        parts = body.split(".")
        if not all(part.isdigit() for part in parts if part):
            return None
        if not any(part for part in parts):
            return None
        if len(parts) == 2 and len(parts[1]) > 3:
            return None
        value = Decimal(text)
        if not value.is_finite():
            return None
        return int((value * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        ))
    except (InvalidOperation, ValueError, TypeError, ArithmeticError):
        return None


def parse_record(line):
    try:
        if not isinstance(line, str):
            return None
        fields = line.split("|")
        if len(fields) != 6:
            return None
        kind = fields[0].strip().upper()
        record_id = fields[1].strip()
        order_id = fields[2].strip()
        currency = fields[4].strip()
        if kind not in ("ORDER", "PAYMENT") or not record_id or not order_id:
            return None
        if currency != "USD":
            return None
        if kind == "ORDER" and record_id != order_id:
            return None
        amount = parse_amount(fields[3])
        if amount is None or (kind == "ORDER" and amount < 0):
            return None
        stamp = fields[5]
        if (len(stamp) != 16 or stamp[4] != "-" or stamp[7] != "-" or
                stamp[10] != " " or stamp[13] != ":"):
            return None
        timestamp = datetime.strptime(stamp, "%Y-%m-%d %H:%M")
        if timestamp.strftime("%Y-%m-%d %H:%M") != stamp:
            return None
        return {
            "type": kind,
            "record_id": record_id,
            "order_id": order_id,
            "amount": amount,
            "currency": "USD",
            "timestamp": timestamp,
        }
    except (ValueError, TypeError, OverflowError):
        return None


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            records.append(record)
    return records


def match_payments(records):
    results = []
    payments = [record for record in records if record["type"] == "PAYMENT"]
    for order in records:
        if order["type"] != "ORDER":
            continue
        chosen = None
        for payment in payments:
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["amount"] < 0:
                continue
            elapsed = payment["timestamp"] - order["timestamp"]
            if elapsed < timedelta(0) or elapsed > timedelta(hours=72):
                continue
            if chosen is None or payment["timestamp"] < chosen["timestamp"]:
                chosen = payment
        if chosen is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": chosen["amount"],
            })
    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += -record["amount"]
    return total


def build_summary(matches, refund_total):
    matched_count = 0
    net_total = 0
    unmatched_ids = []
    for result in matches:
        if result["status"] == "matched":
            matched_count += 1
            net_total += result["amount"]
        else:
            unmatched_ids.append(result["order_id"])
    unmatched_ids.sort()
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

