"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s.strip())
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    parts = line.split('|')
    if len(parts) != 6:
        return None
    record_type, record_id, order_id, amount, currency, timestamp = parts
    record_type = record_type.strip().upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    if record_id == '' or order_id == '':
        return None
    if record_type == 'ORDER' and record_id != order_id:
        return None
    if currency.strip() != 'USD':
        return None
    amount_cents = parse_amount(amount)
    if amount_cents is None:
        return None
    try:
        timestamp = datetime.strptime(timestamp.strip(), '%Y-%m-%d %H:%M')
    except ValueError:
        return None
    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount_cents,
        'currency': currency.strip(),
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    orders = []
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            orders.append(record)
        elif record['type'] == 'PAYMENT':
            payments.append(record)

    results = []

    for order in orders:
        order_id = order['order_id']
        order_timestamp = order['timestamp']
        matched_payment = None

        for payment in payments:
            if payment['amount'] < 0:
                continue  # Skip refunds

            if order_timestamp <= payment['timestamp'] <= order_timestamp + timedelta(hours=72):
                if matched_payment is None or payment['timestamp'] < matched_payment['timestamp']:
                    matched_payment = payment

        if matched_payment:
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': matched_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    # Placeholder for future implementation
    return 0


def build_summary(matches, refund_total):
    total_orders = 0
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for match in matches:
        if match['status'] == 'matched':
            matched_count += 1
            net_total += match['amount']
        else:
            unmatched_ids.append(match['order_id'])

    unmatched_ids.sort()
    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'net_total': net_total - refund_total,
        'unmatched_ids': unmatched_ids
    }

