from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a monetary value to integer cents, or return None if invalid."""
    if not isinstance(s, str):
        return None

    text = s.strip()
    if not text:
        return None

    negative = text.startswith("-")
    digits = text[1:] if negative else text

    if not digits:
        return None
    if digits.count(".") > 1:
        return None

    if "." in digits:
        whole, fraction = digits.split(".")
        if not whole or not whole.isdigit():
            return None
        if not fraction or not fraction.isdigit() or len(fraction) > 3:
            return None
    else:
        whole = digits
        if not whole.isdigit():
            return None

    try:
        value = Decimal(text)
        if not value.is_finite():
            return None
        cents = value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        return int(cents * 100)
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type = fields[0].upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    amount_text = fields[3]
    currency = fields[4]
    timestamp_text = fields[5]

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None

    if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    """Match each order with its earliest qualifying payment."""
    if not isinstance(records, list):
        return []

    orders = []
    payments = []

    for record in records:
        if not isinstance(record, dict):
            continue

        record_type = record.get("type")
        if record_type == "ORDER":
            orders.append(record)
        elif record_type == "PAYMENT":
            amount = record.get("amount")
            if isinstance(amount, int) and amount >= 0:
                payments.append(record)

    results = []

    for order in orders:
        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        latest_time = order_time + timedelta(hours=72)

        best_payment = None

        for payment in payments:
            if payment.get("order_id") != order_id:
                continue

            payment_time = payment.get("timestamp")
            if not isinstance(payment_time, datetime):
                continue

            if order_time <= payment_time <= latest_time:
                if best_payment is None:
                    best_payment = payment
                elif payment_time < best_payment["timestamp"]:
                    best_payment = payment

        if best_payment is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": best_payment["amount"],
            })

    return results


def compute_refunds(records):
    total = 0

    if not isinstance(records, list):
        return total

    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue

        amount = record.get("amount")
        if isinstance(amount, int) and amount < 0:
            total += abs(amount)

    return total


def build_summary(matches, refund_total):
    """Build the summary report for payment-matching results."""
    if not isinstance(matches, list):
        matches = []

    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for result in matches:
        if not isinstance(result, dict):
            continue

        status = result.get("status")

        if status == "matched":
            matched_count += 1

            if "payment_amount" in result:
                amount = result["payment_amount"]
            elif "matched_amount" in result:
                amount = result["matched_amount"]
            else:
                amount = result.get("amount", 0)

            if isinstance(amount, int) and not isinstance(amount, bool):
                net_total += amount

        elif status == "unmatched":
            order_id = result.get("order_id")
            if order_id is not None:
                unmatched_ids.append(order_id)

    if isinstance(refund_total, int) and not isinstance(refund_total, bool):
        if refund_total > 0:
            net_total -= refund_total

    unmatched_ids.sort()

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids,
    }

