"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    import re
    if not isinstance(s, str):
        return None
    text = s.strip()
    if not re.fullmatch(r"-?(?:\d+(?:\.\d{0,3})?|\.\d{1,3})", text):
        return None
    try:
        value = Decimal(text)
        if not value.is_finite():
            return None
        return int((value * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        ))
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
    record_type = fields[0].strip().upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    currency = fields[4].strip()
    timestamp_text = fields[5].strip()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    if currency != "USD":
        return None
    amount = parse_amount(fields[3].strip())
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (ValueError, TypeError):
        return None
    if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        try:
            record = parse_record(line)
        except Exception:
            record = None
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            records.append(record)
    return records


def match_payments(records):
    if not isinstance(records, list):
        return []
    orders = [r for r in records
              if isinstance(r, dict) and r.get("type") == "ORDER"]
    payments = [r for r in records
                if isinstance(r, dict) and r.get("type") == "PAYMENT"]
    results = []
    for order in orders:
        order_id = order.get("order_id")
        start = order.get("timestamp")
        best = None
        if isinstance(start, datetime):
            end = start + timedelta(hours=72)
            for payment in payments:
                if payment.get("order_id") != order_id:
                    continue
                amount = payment.get("amount")
                timestamp = payment.get("timestamp")
                if (isinstance(amount, int) and amount >= 0
                        and isinstance(timestamp, datetime)
                        and start <= timestamp <= end):
                    if best is None or timestamp < best.get("timestamp"):
                        best = payment
        if best is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": best["amount"]
            })
    return results


def compute_refunds(records):
    total = 0
    if not isinstance(records, list):
        return total
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        amount = record.get("amount")
        if isinstance(amount, (int, float, Decimal)) and amount < 0:
            total += abs(amount)
    return total


def build_summary(matches, refund_total):
    matched_count = 0
    net_total = 0
    unmatched_ids = []
    if not isinstance(matches, list):
        matches = []
    for result in matches:
        if not isinstance(result, dict):
            continue
        if result.get("status") == "matched":
            matched_count += 1
            net_total += result.get("amount", 0)
        else:
            unmatched_ids.append(result.get("order_id"))
    unmatched_ids.sort()
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

