"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    value = s.strip()
    if not value:
        return None
    if value.startswith("-"):
        digits = value[1:]
    else:
        digits = value
    if not digits or digits.count(".") > 1:
        return None
    if "." in digits:
        whole, fraction = digits.split(".")
        if not whole and not fraction:
            return None
        if whole and not whole.isdigit():
            return None
        if fraction and not fraction.isdigit():
            return None
        if len(fraction) > 3:
            return None
    elif not digits.isdigit():
        return None
    try:
        amount = Decimal(value)
        cents = (amount * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        )
        return int(cents)
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
    record_type = fields[0].strip().upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    currency = fields[4].strip()
    timestamp_text = fields[5].strip()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    if currency != "USD":
        return None
    amount = parse_amount(fields[3])
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None
    if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if isinstance(record, dict) and record["record_id"] not in seen:
            seen.add(record["record_id"])
            records.append(record)
    return records


def match_payments(records):
    if not isinstance(records, list):
        return []
    payments = {}
    orders = []
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") == "ORDER":
            orders.append(record)
        elif record.get("type") == "PAYMENT":
            payments.setdefault(record.get("order_id"), []).append(record)

    results = []
    window = timedelta(hours=72)
    for order in orders:
        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        selected = None
        if isinstance(order_time, datetime):
            for payment in payments.get(order_id, []):
                payment_time = payment.get("timestamp")
                amount = payment.get("amount")
                if not isinstance(payment_time, datetime):
                    continue
                if not isinstance(amount, int) or amount < 0:
                    continue
                if order_time <= payment_time <= order_time + window:
                    if selected is None or payment_time < selected.get("timestamp"):
                        selected = payment
        if selected is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": selected["amount"],
            })
    return results


def compute_refunds(records):
    if not isinstance(records, list):
        return 0
    total = 0
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") == "PAYMENT":
            amount = record.get("amount")
            if isinstance(amount, int) and amount < 0:
                total += -amount
    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, list):
        matches = []
    matched_count = 0
    net_total = 0
    unmatched_ids = []
    for item in matches:
        if not isinstance(item, dict):
            continue
        if item.get("status") == "matched":
            matched_count += 1
            amount = item.get("amount", 0)
            if isinstance(amount, int):
                net_total += amount
        elif item.get("status") == "unmatched":
            order_id = item.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.append(order_id)
    net_total -= refund_total
    unmatched_ids.sort()
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids,
    }

"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None

    negative = s.startswith("-")
    if negative:
        s = s[1:]

    if s.count(".") > 1 or not s:
        return None

    if "." in s:
        whole, fraction = s.split(".")
    else:
        whole, fraction = s, ""

    if not whole and not fraction:
        return None

    if any(ch not in "0123456789" for ch in whole + fraction):
        return None

    if len(fraction) > 3:
        return None

    whole_value = int(whole) if whole else 0
    cents_text = (fraction + "00")[:2]
    cents = int(cents_text) if cents_text else 0

    if len(fraction) == 3 and fraction[2] >= "5":
        cents += 1

    total_cents = whole_value * 100 + cents
    if negative:
        total_cents = -total_cents

    return total_cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields

    record_type = record_type.strip().upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    currency = currency.strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None

    if not record_id or not order_id:
        return None

    if record_type == "ORDER" and record_id != order_id:
        return None

    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    if (
        len(timestamp_text) != 16
        or timestamp_text[4] != "-"
        or timestamp_text[7] != "-"
        or timestamp_text[10] != " "
        or timestamp_text[13] != ":"
        or any(
            not timestamp_text[index].isdigit()
            for index in (0, 1, 2, 3, 5, 6, 8, 9, 11, 12, 14, 15)
        )
    ):
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    seen_record_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_record_ids:
            continue

        seen_record_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    results = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        order_timestamp = order["timestamp"]
        latest_timestamp = order_timestamp + timedelta(hours=72)
        best_payment = None

        for record in records:
            if record["type"] != "PAYMENT":
                continue
            if record["order_id"] != order["order_id"]:
                continue
            if record["amount"] < 0:
                continue
            if record["timestamp"] < order_timestamp:
                continue
            if record["timestamp"] > latest_timestamp:
                continue

            if (
                best_payment is None
                or record["timestamp"] < best_payment["timestamp"]
            ):
                best_payment = record

        if best_payment is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": best_payment["amount"],
            })

    return results


def compute_refunds(records):
    total = 0

    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += abs(record["amount"])

    return total


def build_summary(matches, refund_total):
    matched_total = sum(
        result["amount"]
        for result in matches
        if result["status"] == "matched"
    )

    unmatched_ids = sorted(
        result["order_id"]
        for result in matches
        if result["status"] != "matched"
    )

    return {
        "total_orders": len(matches),
        "matched_count": sum(
            1 for result in matches
            if result["status"] == "matched"
        ),
        "net_total": matched_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

