from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None

    negative = s.startswith("-")
    value = s[1:] if negative else s

    if not value or value.count(".") > 1:
        return None

    if "." in value:
        whole, fractional = value.split(".")
    else:
        whole, fractional = value, ""

    if not whole and not fractional:
        return None

    if whole and not all("0" <= char <= "9" for char in whole):
        return None
    if fractional and not all("0" <= char <= "9" for char in fractional):
        return None
    if len(fractional) > 3:
        return None

    whole_cents = int(whole or "0") * 100
    fractional_cents = int((fractional + "00")[:2] or "0")

    if len(fractional) == 3 and fractional[2] >= "5":
        fractional_cents += 1

    result = whole_cents + fractional_cents
    return -result if negative else result


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type = fields[0]
    if record_type.upper() not in ("ORDER", "PAYMENT"):
        return None
    record_type = record_type.upper()

    record_id = fields[1].strip()
    order_id = fields[2].strip()
    if not record_id or not order_id:
        return None

    if record_type == "ORDER" and record_id != order_id:
        return None

    currency = fields[4].strip()
    if currency != "USD":
        return None

    amount = parse_amount(fields[3])
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    timestamp_text = fields[5]
    if (
        len(timestamp_text) != 16
        or timestamp_text[4] != "-"
        or timestamp_text[7] != "-"
        or timestamp_text[10] != " "
        or timestamp_text[13] != ":"
        or not timestamp_text[:4].isdigit()
        or not timestamp_text[5:7].isdigit()
        or not timestamp_text[8:10].isdigit()
        or not timestamp_text[11:13].isdigit()
        or not timestamp_text[14:16].isdigit()
    ):
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    seen_record_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_record_ids:
            continue

        seen_record_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    results = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        start_time = order["timestamp"]
        end_time = start_time + timedelta(hours=72)
        chosen_payment = None

        for payment in records:
            if payment["type"] != "PAYMENT":
                continue
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["amount"] < 0:
                continue
            if payment["timestamp"] < start_time:
                continue
            if payment["timestamp"] > end_time:
                continue

            if (
                chosen_payment is None
                or payment["timestamp"] < chosen_payment["timestamp"]
            ):
                chosen_payment = payment

        if chosen_payment is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": chosen_payment["amount"],
            })

    return results


def compute_refunds(records):
    total = 0

    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += abs(record["amount"])

    return total


def build_summary(matches, refund_total):
    matched_amount = 0
    matched_count = 0
    unmatched_ids = []

    for result in matches:
        if result["status"] == "matched":
            matched_count += 1
            matched_amount += result["amount"]
        else:
            unmatched_ids.append(result["order_id"])

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": matched_amount - refund_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Parse a string amount into an integer number of cents."""
    try:
        # Convert the string to a Decimal, then to an integer in cents
        amount = Decimal(s.strip())
        return int(amount * 100)  # Convert dollars to cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    """Parse a single record line into a dictionary."""
    fields = line.strip().split('|')

    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_str, currency, timestamp_str = map(str.strip, fields)

    # Normalize type to uppercase
    record_type = record_type.upper()

    # Validate type
    if record_type not in {"ORDER", "PAYMENT"}:
        return None

    # Validate record_id and order_id for ORDER type
    if record_type == "ORDER" and record_id != order_id:
        return None

    # Validate amount
    amount = parse_amount(amount_str)
    if amount is None:
        return None

    # Validate currency
    if currency != "USD":
        return None

    # Validate timestamp format
    try:
        timestamp = datetime.strptime(timestamp_str, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp
    }


def load_records(text):
    """Load records from a text input, returning a list of valid record dictionaries."""
    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record not in records:
            records.append(record)
    return records


def match_payments(records):
    """Match payments to orders based on order_id and timestamp criteria."""
    orders = []
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            orders.append(record)
        elif record['type'] == 'PAYMENT':
            payments.append(record)

    results = []

    for order in orders:
        order_id = order['order_id']
        order_timestamp = order['timestamp']
        end_timestamp = order_timestamp + timedelta(hours=72)

        # Filter payments that qualify for this order
        qualifying_payments = [
            payment for payment in payments
            if (payment['order_id'] == order_id and
                order_timestamp <= payment['timestamp'] <= end_timestamp and
                payment['amount'] >= 0)
        ]

        if qualifying_payments:
            # Sort by timestamp, then by original order
            qualifying_payments.sort(key=lambda p: (p['timestamp'], payments.index(p)))
            best_payment = qualifying_payments[0]
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": best_payment['amount']
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0
            })

    return results


def compute_refunds(records):
    """Compute the total amount of refunds from the records."""
    refund_total = 0

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0:
            refund_total += -record['amount']  # Add the positive value of the refund

    return refund_total


def build_summary(matches, refund_total):
    """Build a summary report from matched results."""
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched')
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'] != 'matched')

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids
    }

