"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    if not s:
        return None

    negative = s.startswith("-")
    text = s[1:] if negative else s
    if not text:
        return None
    if text.count(".") > 1:
        return None

    parts = text.split(".")
    whole = parts[0]
    fraction = parts[1] if len(parts) == 2 else ""

    if not whole and not fraction:
        return None
    if whole and not all(char in "0123456789" for char in whole):
        return None
    if fraction and not all(char in "0123456789" for char in fraction):
        return None
    if len(fraction) > 3:
        return None

    try:
        value = Decimal(s).quantize(
            Decimal("0.01"), rounding=ROUND_HALF_UP
        )
        return int(value * 100)
    except (InvalidOperation, ValueError, TypeError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    type_text, record_id, order_id, amount_text, currency, timestamp_text = fields
    record_type = type_text.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()
    currency = currency.strip()

    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    if len(timestamp_text) != 16:
        return None
    expected = {4: "-", 7: "-", 10: " ", 13: ":"}
    for position, character in enumerate(timestamp_text):
        if position in expected:
            if character != expected[position]:
                return None
        elif character not in "0123456789":
            return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue
        record_id = record["record_id"]
        if record_id in seen_ids:
            continue
        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    results = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        earliest = order["timestamp"]
        latest = earliest + timedelta(hours=72)
        selected = None

        for payment in records:
            if payment["type"] != "PAYMENT":
                continue
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["amount"] < 0:
                continue
            if payment["timestamp"] < earliest:
                continue
            if payment["timestamp"] > latest:
                continue
            if selected is None or payment["timestamp"] < selected["timestamp"]:
                selected = payment

        if selected is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": selected["amount"],
            })

    return results


def compute_refunds(records):
    total = 0

    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += abs(record["amount"])

    return total


def build_summary(matches, refund_total):
    matched_count = 0
    matched_total = 0
    unmatched_ids = []

    for match in matches:
        if match["status"] == "matched":
            matched_count += 1
            matched_total += match["amount"]
        else:
            unmatched_ids.append(match["order_id"])

    unmatched_ids.sort()

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": matched_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

