"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    s = s.strip()
    try:
        amount = Decimal(s) * 100
        return int(amount.to_integral_value(rounding=ROUND_HALF_UP))
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.upper().strip()
    record_id = record_id.strip()
    order_id = order_id.strip()
    amount = amount.strip()
    currency = currency.strip()
    timestamp = timestamp.strip()

    if not (record_id and order_id and amount and currency and timestamp):
        return None
    if record_type == 'ORDER' and record_id != order_id:
        return None
    if currency != 'USD':
        return None

    try:
        amount = parse_amount(amount)
        if amount is None:
            return None
    except Exception:
        return None

    try:
        timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    lines = text.strip().splitlines()
    records = [parse_record(line) for line in lines]
    return [record for record in records if record is not None]


def match_payments(records):
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = [record for record in records if record['type'] == 'PAYMENT']
    results = []

    for order in orders:
        order_id = order['order_id']
        order_timestamp = order['timestamp']
        qualifying_payments = [
            payment for payment in payments
            if (payment['order_id'] == order_id and
                order_timestamp <= payment['timestamp'] <= order_timestamp + timedelta(hours=72) and
                payment['amount'] >= 0)
        ]

        if qualifying_payments:
            earliest_payment = min(qualifying_payments, key=lambda p: p['timestamp'])
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': earliest_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    raise NotImplementedError


def build_summary(matches, refund_total):
    total_orders = 0
    matched_count = 0
    net_total = 0
    unmatched_ids = set()

    for match in matches:
        if match['status'] == 'matched':
            matched_count += 1
            net_total += match['amount']
        elif match['status'] == 'unmatched':
            unmatched_ids.add(match['order_id'])

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'net_total': net_total,
        'unmatched_ids': sorted(unmatched_ids)
    }

