"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None

    negative = s.startswith("-")
    body = s[1:] if negative else s
    if not body or body.count(".") > 1:
        return None

    parts = body.split(".")
    whole = parts[0]
    fractional = parts[1] if len(parts) == 2 else ""

    if not whole and not fractional:
        return None
    if not all(character.isdigit() for character in whole + fractional):
        return None
    if len(fractional) > 3:
        return None

    try:
        amount = Decimal(s)
        cents = amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        return int(cents * 100)
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    currency = currency.strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    if (
        len(timestamp_text) != 16
        or timestamp_text[4] != "-"
        or timestamp_text[7] != "-"
        or timestamp_text[10] != " "
        or timestamp_text[13] != ":"
    ):
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    results = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        order_time = order["timestamp"]
        deadline = order_time + timedelta(hours=72)
        best_payment = None

        for record in records:
            if record["type"] != "PAYMENT":
                continue
            if record["order_id"] != order["order_id"]:
                continue
            if record["amount"] < 0:
                continue
            if record["timestamp"] < order_time:
                continue
            if record["timestamp"] > deadline:
                continue

            if (
                best_payment is None
                or record["timestamp"] < best_payment["timestamp"]
            ):
                best_payment = record

        if best_payment is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": best_payment["amount"],
            })

    return results


def compute_refunds(records):
    total = 0

    for record in records:
        if record["type"] != "PAYMENT":
            continue
        if record["amount"] >= 0:
            continue
        total += -record["amount"]

    return total


def build_summary(matches, refund_total):
    matched_count = 0
    matched_total = 0
    unmatched_ids = []

    for result in matches:
        if result["status"] == "matched":
            matched_count += 1
            matched_total += result["amount"]
        else:
            unmatched_ids.append(result["order_id"])

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": matched_total - refund_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

