"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None
    negative = False
    if s[0] == "-":
        negative = True
        s = s[1:]
    if not s or s.count(".") > 1:
        return None
    if "." in s:
        whole, fraction = s.split(".")
    else:
        whole, fraction = s, ""
    if not whole and not fraction:
        return None
    if any(ch < "0" or ch > "9" for ch in whole + fraction):
        return None
    if len(fraction) > 3:
        return None
    cents = (int(whole) if whole else 0) * 100
    cents += int((fraction + "00")[:2])
    if len(fraction) == 3 and fraction[2] >= "5":
        cents += 1
    return -cents if negative else cents


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    currency = currency.strip()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    if currency != "USD":
        return None
    amount = parse_amount(amount_text)
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None
    if (
        len(timestamp_text) != 16
        or timestamp_text[4] != "-"
        or timestamp_text[7] != "-"
        or timestamp_text[10] != " "
        or timestamp_text[13] != ":"
        or not all(timestamp_text[i].isdigit() for i in
                   (0, 1, 2, 3, 5, 6, 8, 9, 11, 12, 14, 15))
    ):
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (ValueError, TypeError):
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen_ids = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen_ids:
            seen_ids.add(record["record_id"])
            records.append(record)
    return records


def match_payments(records):
    results = []
    for order in records:
        if order["type"] != "ORDER":
            continue
        order_time = order["timestamp"]
        end_time = order_time + timedelta(hours=72)
        best = None
        for payment in records:
            if payment["type"] != "PAYMENT":
                continue
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["amount"] < 0:
                continue
            if not (order_time <= payment["timestamp"] <= end_time):
                continue
            if best is None or payment["timestamp"] < best["timestamp"]:
                best = payment
        if best is None:
            results.append({"order_id": order["order_id"],
                            "status": "unmatched", "amount": 0})
        else:
            results.append({"order_id": order["order_id"],
                            "status": "matched", "amount": best["amount"]})
    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += -record["amount"]
    return total


def build_summary(matches, refund_total):
    matched_count = 0
    net_total = 0
    unmatched_ids = []
    for result in matches:
        if result["status"] == "matched":
            matched_count += 1
            net_total += result["amount"]
        else:
            unmatched_ids.append(result["order_id"])
    unmatched_ids.sort()
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

