    text = s
    if text.startswith("-"):
        text = text[1:]

    if text == "" or any(
        character not in "0123456789." for character in text
    ):
        return None

    if text.count(".") > 1:
        return None

    integer_part, separator, fractional_part = text.partition(".")

    if integer_part == "" and fractional_part == "":
        return None

    if fractional_part and len(fractional_part) > 3:
        return None

    try:
        value = Decimal(s)
        rounded = value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        return int(rounded * 100)
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    type_field, record_id, order_id, amount_text, currency, timestamp_text = (
        fields
    )

    record_type = type_field.upper()
    if record_type not in ("ORDER", "PAYMENT"):
