        len(timestamp_text) != 16
        or timestamp_text[4] != "-"
        or timestamp_text[7] != "-"
        or timestamp_text[10] != " "
        or timestamp_text[13] != ":"
        or any(
            not character.isdigit()
            for index, character in enumerate(timestamp_text)
            if index not in (4, 7, 10, 13)
        )
    ):
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": "USD",
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    seen_record_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_record_ids:
            continue

        seen_record_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    results = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        earliest_time = order["timestamp"]
        latest_time = earliest_time + timedelta(hours=72)
        best_payment = None

        for record in records:
            if record["type"] != "PAYMENT":
                continue
            if record["order_id"] != order["order_id"]:
                continue
            if record["amount"] < 0:
                continue

            payment_time = record["timestamp"]
            if earliest_time <= payment_time <= latest_time:
                if (
                    best_payment is None
                    or payment_time < best_payment["timestamp"]
                ):
                    best_payment = record

        if best_payment is None:
            results.append(
                {
                    "order_id": order["order_id"],
                    "status": "unmatched",
                    "amount": 0,
                }
            )
        else:
            results.append(
                {
                    "order_id": order["order_id"],
                    "status": "matched",
                    "amount": best_payment["amount"],
                }
            )

    return results


def compute_refunds(records):
    total = 0

    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += -record["amount"]

    return total


def build_summary(matches, refund_total):
    matched_total = 0
    unmatched_ids = []
    matched_count = 0

    for result in matches:
        if result["status"] == "matched":
            matched_count += 1
            matched_total += result["amount"]
        else:
            unmatched_ids.append(result["order_id"])

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": matched_total - refund_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

