"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Return a monetary value as integer cents, or None if invalid."""
    if not isinstance(s, str):
        return None
    value = s.strip()
    if not value:
        return None

    negative = value.startswith("-")
    digits = value[1:] if negative else value
    if not digits:
        return None

    if "." in digits:
        if digits.count(".") != 1:
            return None
        whole, fraction = digits.split(".")
        if not whole and not fraction:
            return None
        if any(char not in "0123456789" for char in whole + fraction):
            return None
        if len(fraction) > 3:
            return None
    else:
        if any(char not in "0123456789" for char in digits):
            return None

    try:
        amount = Decimal(value)
        return int((amount * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        ))
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    """Parse one input line, returning a record or None."""
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type = fields[0].strip().upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    currency = fields[4].strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id or currency != "USD":
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(fields[3])
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None

    timestamp_text = fields[5]
    if len(timestamp_text) != 16:
        return None
    if (
        timestamp_text[4],
        timestamp_text[7],
        timestamp_text[10],
        timestamp_text[13],
    ) != ("-", "-", " ", ":"):
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    """Parse all records in a text export."""
    if not isinstance(text, str):
        return []

    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            records.append(record)
    return records


def match_payments(records):
    """Match each order with its earliest qualifying payment."""
    orders = [record for record in records if record["type"] == "ORDER"]
    payments = [record for record in records if record["type"] == "PAYMENT"]
    results = []

    for order in orders:
        cutoff = order["timestamp"] + timedelta(hours=72)
        chosen = None

        for payment in payments:
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["amount"] < 0:
                continue
            if order["timestamp"] <= payment["timestamp"] <= cutoff:
                if chosen is None or payment["timestamp"] < chosen["timestamp"]:
                    chosen = payment

        if chosen is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": chosen["amount"],
            })

    return results


def compute_refunds(records):
    """Compute the total refunds in integer cents."""
    return sum(
        -record["amount"]
        for record in records
        if record["type"] == "PAYMENT" and record["amount"] < 0
    )


def build_summary(matches, refund_total):
    """Build a summary from matches and a refund total."""
    matched = [
        result for result in matches
        if result["status"] == "matched"
    ]
    return {
        "total_orders": len(matches),
        "matched_count": len(matched),
        "net_total": (
            sum(result["amount"] for result in matched) - refund_total
        ),
        "unmatched_ids": sorted(
            result["order_id"]
            for result in matches
            if result["status"] == "unmatched"
        ),
    }

