"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s.strip())
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    parts = line.split('|')
    if len(parts) != 6:
        return None
    record_type, record_id, order_id, amount, currency, timestamp = parts
    record_type = record_type.strip().upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    if currency.strip() != 'USD' or not record_id or not order_id:
        return None
    if record_type == 'ORDER' and record_id != order_id:
        return None
    parsed_amount = parse_amount(amount)
    if parsed_amount is None:
        return None
    try:
        timestamp = datetime.strptime(timestamp.strip(), '%Y-%m-%d %H:%M')
    except ValueError:
        return None
    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': parsed_amount,
        'currency': currency.strip(),
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = [record for record in records if record['type'] == 'PAYMENT']
    results = []

    for order in orders:
        order_id = order['order_id']
        order_timestamp = order['timestamp']
        matched_payment = None

        for payment in payments:
            if payment['order_id'] == order_id and payment['amount'] >= 0:
                if order_timestamp <= payment['timestamp'] <= order_timestamp + timedelta(hours=72):
                    if matched_payment is None or payment['timestamp'] < matched_payment['timestamp']:
                        matched_payment = payment

        if matched_payment:
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': matched_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    refunds = 0
    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0:
            refunds += abs(record['amount'])
    return refunds


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = 0
    net_total = 0
    unmatched_ids = set()

    for match in matches:
        if match['status'] == 'matched':
            matched_count += 1
            net_total += match['amount']
        else:
            unmatched_ids.add(match['order_id'])

    net_total -= refund_total

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'net_total': net_total,
        'unmatched_ids': sorted(unmatched_ids)
    }

