from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None

    if s.startswith("-"):
        negative = True
        text = s[1:]
    else:
        negative = False
        text = s

    if not text or text.count(".") > 1:
        return None

    if "." in text:
        whole, fraction = text.split(".")
    else:
        whole, fraction = text, ""

    if not whole and not fraction:
        return None

    if any(ch < "0" or ch > "9" for ch in whole + fraction):
        return None

    if len(fraction) > 3:
        return None

    whole_cents = int(whole or "0") * 100
    fraction_cents = int((fraction + "00")[:2])
    rounded = whole_cents + fraction_cents

    if len(fraction) == 3 and fraction[2] >= "5":
        rounded += 1

    return -rounded if negative else rounded


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    type_text, record_id, order_id, amount_text, currency, timestamp_text = fields

    record_type = type_text.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id:
        return None

    if record_type == "ORDER" and record_id != order_id:
        return None

    if currency.strip() != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    if (
        len(timestamp_text) != 16
        or timestamp_text[4] != "-"
        or timestamp_text[7] != "-"
        or timestamp_text[10] != " "
        or timestamp_text[13] != ":"
        or not all(
            timestamp_text[index].isdigit()
            for index in (
                0, 1, 2, 3, 5, 6, 8, 9, 11, 12, 14, 15
            )
        )
    ):
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": "USD",
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    results = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        order_time = order["timestamp"]
        latest_time = order_time + timedelta(hours=72)
        best_payment = None

        for record in records:
            if record["type"] != "PAYMENT":
                continue
            if record["order_id"] != order["order_id"]:
                continue
            if record["amount"] < 0:
                continue
            if record["timestamp"] < order_time:
                continue
            if record["timestamp"] > latest_time:
                continue

            if (
                best_payment is None
                or record["timestamp"] < best_payment["timestamp"]
            ):
                best_payment = record

        if best_payment is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": best_payment["amount"],
            })

    return results


def compute_refunds(records):
    total = 0

    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += abs(record["amount"])

    return total


def build_summary(matches, refund_total):
    matched_total = sum(
        result["amount"]
        for result in matches
        if result["status"] == "matched"
    )

    unmatched_ids = sorted(
        result["order_id"]
        for result in matches
        if result["status"] == "unmatched"
    )

    return {
        "total_orders": len(matches),
        "matched_count": sum(
            1 for result in matches if result["status"] == "matched"
        ),
        "net_total": matched_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

