    }

"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a monetary value to an integer number of cents.

    Invalid values return None instead of raising an exception.
    """
    if not isinstance(s, str):
        return None

    value = s.strip()
    if not value:
        return None

    if value.startswith("-"):
        digits = value[1:]
    else:
        digits = value

    if not digits:
        return None

    if digits.count(".") > 1:
        return None

    parts = digits.split(".")
    whole = parts[0]
    fraction = parts[1] if len(parts) == 2 else ""

    if not whole and not fraction:
        return None
    if not whole:
        whole = "0"

    if not whole.isdigit() or not fraction.isdigit():
        return None
    if len(fraction) > 3:
        return None

    try:
        amount = Decimal(value)
        if not amount.is_finite():
            return None

        amount = amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        return int(amount * 100)
    except (InvalidOperation, TypeError, ValueError, OverflowError):
        return None


def parse_record(line):
    """Parse one input line."""
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type = fields[0].strip().upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    amount_text = fields[3]
    currency = fields[4]
    timestamp_text = fields[5]

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None

    if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": "USD",
        "timestamp": timestamp,
    }


def load_records(text):
    """Parse all valid records from a text export."""
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        try:
            record = parse_record(line)
        except Exception:
            record = None

        if isinstance(record, dict):
            record_id = record["record_id"]
            if record_id in seen_ids:
                continue
            seen_ids.add(record_id)
            records.append(record)

    return records


def match_payments(records):
    """Return the earliest qualifying payment for each order."""
    payments_by_order = {}

    for source_index, record in enumerate(records):
        if record.get("type") != "PAYMENT":
            continue
        if record.get("amount", 0) < 0:
            continue

        order_id = record.get("order_id")
        payments_by_order.setdefault(order_id, []).append(
            (record["timestamp"], source_index, record["amount"])
        )

    results = []

    for record in records:
        if record.get("type") != "ORDER":
            continue

        order_id = record["order_id"]
        order_time = record["timestamp"]
        deadline = order_time + timedelta(hours=72)

        qualifying = [
            payment
            for payment in payments_by_order.get(order_id, [])
            if order_time <= payment[0] <= deadline
        ]

        if qualifying:
            qualifying.sort(key=lambda payment: (payment[0], payment[1]))
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": qualifying[0][2],
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })

    return results


def compute_refunds(records):
    """Return the total refunds in cents."""
    total = 0

    for record in records:
        if record.get("type") == "PAYMENT":
            amount = record.get("amount")
            if isinstance(amount, int) and amount < 0:
                total += -amount

    return total


def build_summary(matches, refund_total):
    """Build a settlement summary."""
    matched_count = 0
    matched_total = 0
    unmatched_ids = []

    for result in matches:
        if result.get("status") == "matched":
            matched_count += 1
            matched_total += result.get("amount", 0)
        else:
            unmatched_ids.append(result.get("order_id"))

    unmatched_ids.sort()

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": matched_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

