"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    value = s.strip()
    if not value:
        return None
    body = value[1:] if value.startswith("-") else value
    if not body or body.count(".") > 1:
        return None
    if "." in body:
        whole, fraction = body.split(".")
        if not whole or not whole.isdigit() or not fraction.isdigit() or len(fraction) > 3:
            return None
    elif not body.isdigit():
        return None
    try:
        amount = Decimal(value)
        if not amount.is_finite():
            return None
        return int((amount * Decimal("100")).quantize(Decimal("1"), rounding=ROUND_HALF_UP))
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
    record_type = fields[0].strip().upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    currency = fields[4].strip()
    timestamp_text = fields[5]
    if record_type not in ("ORDER", "PAYMENT") or not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    if currency != "USD":
        return None
    amount = parse_amount(fields[3])
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (ValueError, TypeError):
        return None
    if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            records.append(record)
    return records


def match_payments(records):
    results = []
    for order in records:
        if order.get("type") != "ORDER":
            continue
        best = None
        deadline = order["timestamp"] + timedelta(hours=72)
        for payment in records:
            if payment.get("type") != "PAYMENT":
                continue
            if payment.get("order_id") != order.get("order_id"):
                continue
            if payment.get("amount", 0) < 0:
                continue
            timestamp = payment.get("timestamp")
            if order["timestamp"] <= timestamp <= deadline:
                if best is None or timestamp < best["timestamp"]:
                    best = payment
        if best is None:
            results.append({"order_id": order["order_id"], "status": "unmatched", "amount": 0})
        else:
            results.append({"order_id": order["order_id"], "status": "matched", "amount": best["amount"]})
    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if record.get("type") == "PAYMENT" and record.get("amount", 0) < 0:
            total += -record["amount"]
    return total


def build_summary(matches, refund_total):
    matched_count = 0
    net_total = 0
    unmatched_ids = []
    for result in matches:
        if result["status"] == "matched":
            matched_count += 1
            net_total += result["amount"]
        else:
            unmatched_ids.append(result["order_id"])
    unmatched_ids.sort()
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

